  1	//! Acquisition and offline loading, with separate infrastructure capabilities.
  2	use crate::domain::{
  3	    models::{
  4	        entity_ingestion::{
  5	            EntityIngestionError, EntityIngestionOutcome, EntityIngestionRequest,
  6	            EntityIngestionTarget, MemberIngestionStage,
  7	        },
  8	        member_ingestion::{
  9	            CaptureContext, CaptureId, MemberCapture, MemberObservations, MemberProfile, invalid,
 10	        },
 11	    },
 12	    repositories::{
 13	        entity_ingestion_pipline::EntityIngestionStorage, member_writer::MemberWriter,
 14	        parliament_api::ParliamentApi,
 15	    },
 16	};
 17	use chrono::{DateTime, NaiveDate, Utc};
 18	use interface::EntitySearchIngestionService;
 19	use std::collections::{BTreeMap, BTreeSet};
 20	
 21	/// Public service boundary used by inbound adapters.
 22	pub mod interface;
 23	
 24	/// Capture orchestration. It has no database capability.
 25	#[derive(Clone)]
 26	pub struct FetchService<S, P> {
 27	    storage: S,
 28	    source: P,
 29	    started_at: DateTime<Utc>,
 30	    observation_date: NaiveDate,
 31	}
 32	impl<S, P> FetchService<S, P> {
 33	    /// Supply source/storage adapters and one fixed observation context.
 34	    #[must_use]
 35	    pub const fn new(
 36	        storage: S,
 37	        source: P,
 38	        started_at: DateTime<Utc>,
 39	        observation_date: NaiveDate,
 40	    ) -> Self {
 41	        Self {
 42	            storage,
 43	            source,
 44	            started_at,
 45	            observation_date,
 46	        }
 47	    }
 48	}
 49	impl<S: EntityIngestionStorage, P: ParliamentApi> EntitySearchIngestionService
 50	    for FetchService<S, P>
 51	{
 52	    async fn run_ingestion(
 53	        &self,
 54	        req: &EntityIngestionRequest,
 55	    ) -> Result<EntityIngestionOutcome, EntityIngestionError> {
 56	        let capture_id = CaptureId::new();
 57	        let EntityIngestionTarget::Members(MemberIngestionStage::Fetch { term_start }) =
 58	            req.target()
 59	        else {
 60	            return Err(EntityIngestionError::InvalidStage(
 61	                "this service supports member Fetch".into(),
 62	            ));
 63	        };
 64	        if *term_start > self.observation_date {
 65	            return Err(invalid("term start is after observation date"));
 66	        }
 67	        eprintln!("Capture {capture_id}: fetching current Commons observations");
 68	        let current_commons = unique_profiles(self.source.current_commons().await?)?
 69	            .into_keys()
 70	            .collect();
 71	        eprintln!(
 72	            "Capture {capture_id}: fetching historical Commons candidates since {term_start}"
 73	        );
 74	        let profiles = unique_profiles(
 75	            self.source
 76	                .commons_candidates(*term_start, self.observation_date)
 77	                .await?,
 78	        )?;
 79	        let ids: Vec<_> = profiles.keys().copied().collect();
 80	        let mut histories = Vec::new();
 81	        for batch in ids.chunks(100) {
 82	            let returned = self.source.member_histories(batch).await?;
 83	            let returned_ids: BTreeSet<_> =
 84	                returned.iter().map(|h| h.parliament_member_id).collect();
 85	            if returned_ids.len() != returned.len()
 86	                || returned_ids != batch.iter().copied().collect()
 87	            {
 88	                return Err(invalid(format!(
 89	                    "history response must match requested member IDs exactly: {batch:?}; returned {returned_ids:?}"
 90	                )));
 91	            }
 92	            histories.extend(returned);
 93	        }
 94	        histories.sort_by_key(|history| history.parliament_member_id);
 95	        let observations = MemberObservations {
 96	            profiles: profiles.into_values().collect(),
 97	            current_commons,
 98	            histories,
 99	        };
100	        observations.validate()?;
101	        let counts = observations.counts();
102	        let capture = MemberCapture {
103	            context: CaptureContext {
104	                capture_id,
105	                term_start: *term_start,
106	                observation_date: self.observation_date,
107	                started_at: self.started_at,
108	            },
109	            observations,
110	        };
111	        let capture_id = self.storage.write_member_capture(capture).await?;
112	        Ok(EntityIngestionOutcome::Fetch { capture_id, counts })
113	    }
114	}
115	
116	/// Offline loading. Source access is absent from its contract.
117	#[derive(Clone)]
118	pub struct LoadService<S, W> {
119	    storage: S,
120	    writer: W,
121	}
122	impl<S, W> LoadService<S, W> {
123	    /// Supply completed-capture storage and an atomic member writer.
124	    #[must_use]
125	    pub const fn new(storage: S, writer: W) -> Self {
126	        Self { storage, writer }
127	    }
128	}
129	impl<S: EntityIngestionStorage, W: MemberWriter> EntitySearchIngestionService
130	    for LoadService<S, W>
131	{
132	    async fn run_ingestion(
133	        &self,
134	        req: &EntityIngestionRequest,
135	    ) -> Result<EntityIngestionOutcome, EntityIngestionError> {
136	        let EntityIngestionTarget::Members(MemberIngestionStage::Load { capture_id }) =
137	            req.target()
138	        else {
139	            return Err(EntityIngestionError::InvalidStage(
140	                "this service supports member Load".into(),
141	            ));
142	        };
143	        eprintln!("Capture {capture_id}: validating offline member data");
144	        let capture = self.storage.read_member_capture(*capture_id).await?;
145	        let refresh = capture.prepare_refresh()?;
146	        eprintln!(
147	            "Capture {capture_id}: loading {} eligible members",
148	            refresh.members.len()
149	        );
150	        let summary = self.writer.refresh_members(&refresh).await?;
151	        Ok(EntityIngestionOutcome::Load {
152	            capture_id: *capture_id,
153	            term_start: capture.context.term_start,
154	            observation_date: capture.context.observation_date,
155	            summary,
156	        })
157	    }
158	}
159	
160	fn unique_profiles(
161	    profiles: Vec<MemberProfile>,
162	) -> Result<BTreeMap<i32, MemberProfile>, EntityIngestionError> {
163	    let mut unique = BTreeMap::new();
164	    for profile in profiles {
165	        let id = profile.parliament_member_id;
166	        if id <= 0 {
167	            return Err(invalid(format!(
168	                "member {id}: source identity must be positive"
169	            )));
170	        }
171	        if let Some(previous) = unique.get(&id) {
172	            if previous != &profile {
173	                return Err(invalid(format!(
174	                    "member {id}: conflicting duplicate profile"
175	                )));
176	            }
177	            eprintln!("Member {id}: identical repeated profile collapsed");
178	        } else {
179	            unique.insert(id, profile);
180	        }
181	    }
182	    Ok(unique)
183	}

