  1	//! Sequential Members API requests, typed decoding and bounded retries.
  2	use crate::domain::{
  3	    models::member_ingestion::{HouseMembership, MemberHistory, MemberProfile},
  4	    repositories::parliament_api::{ParliamentApi, ParliamentApiError},
  5	};
  6	use chrono::{DateTime, NaiveDate, NaiveDateTime};
  7	use reqwest::{Client, StatusCode, Url};
  8	use serde::{Deserialize, de::DeserializeOwned};
  9	use serde_json::Value;
 10	use std::{
 11	    fmt::Display,
 12	    time::{Duration, SystemTime},
 13	};
 14	
 15	/// Production HTTP source for the Commons cohort.
 16	#[derive(Clone)]
 17	pub struct MembersApi {
 18	    client: Client,
 19	    base_url: Url,
 20	}
 21	impl MembersApi {
 22	    /// Build an HTTP client without issuing requests.
 23	    ///
 24	    /// # Errors
 25	    /// Rejects invalid URLs or HTTP client configuration.
 26	    pub fn new(base_url: &str) -> Result<Self, ParliamentApiError> {
 27	        let base_url = Url::parse(base_url).map_err(|_| failure("invalid Members API URL"))?;
 28	        if !matches!(base_url.scheme(), "http" | "https")
 29	            || base_url.host_str().is_none()
 30	            || !base_url.username().is_empty()
 31	            || base_url.password().is_some()
 32	        {
 33	            return Err(failure(
 34	                "Members API URL must be an HTTP(S) URL without credentials",
 35	            ));
 36	        }
 37	        let client = Client::builder()
 38	            .connect_timeout(Duration::from_secs(10))
 39	            .timeout(Duration::from_secs(30))
 40	            .build()
 41	            .map_err(failure)?;
 42	        Ok(Self { client, base_url })
 43	    }
 44	
 45	    async fn get(
 46	        &self,
 47	        path: &str,
 48	        params: &[(&str, String)],
 49	    ) -> Result<Vec<u8>, ParliamentApiError> {
 50	        let mut url = self.base_url.join(path).map_err(failure)?;
 51	        url.query_pairs_mut()
 52	            .extend_pairs(params.iter().map(|(key, value)| (*key, value.as_str())));
 53	        // Request context contains source filters/IDs, never connection credentials.
 54	        let context = format!("{path}?{}", url.query().unwrap_or_default());
 55	        for attempt in 0..4 {
