 62	                        match response.bytes().await {
 63	                            Ok(bytes) => return Ok(bytes.to_vec()),
 64	                            Err(error) => format!("response transport failure: {error}"),
 65	                        }
 66	                    } else {
 67	                        if status != StatusCode::TOO_MANY_REQUESTS && !status.is_server_error() {
 68	                            return Err(failure(format!("{context}: HTTP {status}")));
 69	                        }
 70	                        if let Some(header) = response
 71	                            .headers()
 72	                            .get(reqwest::header::RETRY_AFTER)
 73	                            .and_then(|h| h.to_str().ok())
 74	                        {
 75	                            delay = retry_delay(header).unwrap_or(delay);
 76	                        }
 77	                        format!("HTTP {status}")
 78	                    }
 79	                }
 80	                Err(error) => format!("transport failure: {error}"),
 81	            };
 82	            if attempt == 3 {
 83	                return Err(failure(format!("{context}: {problem} after four attempts")));
 84	            }
 85	            eprintln!("{context}: {problem}; retry {}/4", attempt + 2);
 86	            tokio::time::sleep(delay.min(Duration::from_secs(30))).await;
 87	        }
 88	        unreachable!("four attempts always return success or failure")
 89	    }
