198	fn failure(message: impl Display) -> ParliamentApiError {
199	    ParliamentApiError(message.to_string())
200	}
201	fn decode<T: DeserializeOwned>(bytes: &[u8], context: &str) -> Result<T, ParliamentApiError> {
202	    let mut deserializer = serde_json::Deserializer::from_slice(bytes);
203	    let result = serde_path_to_error::deserialize(&mut deserializer)
204	        .map_err(|error| failure(format!("{context}: {error}")))?;
205	    deserializer
206	        .end()
207	        .map_err(|error| failure(format!("{context}: {error}")))?;
208	    Ok(result)
209	}
210	fn decode_item<T: DeserializeOwned>(value: Value, context: &str) -> Result<T, ParliamentApiError> {
211	    let id = value
212	        .pointer("/value/id")
213	        .map_or_else(|| "unknown".into(), Value::to_string);
214	    serde_path_to_error::deserialize(value)
215	        .map_err(|error| failure(format!("{context}, member {id}: {error}")))
216	}
217	fn retry_delay(header: &str) -> Option<Duration> {
218	    if let Ok(seconds) = header.parse::<f64>() {
219	        return seconds
220	            .is_finite()
221	            .then(|| Duration::from_secs_f64(seconds.clamp(0.0, 30.0)));
222	    }
223	    httpdate::parse_http_date(header).ok().map(|date| {
224	        date.duration_since(SystemTime::now())
225	            .unwrap_or_default()
226	            .min(Duration::from_secs(30))
227	    })
228	}
