282	            .or_else(|_| {
283	                NaiveDateTime::parse_from_str(&value, "%Y-%m-%dT%H:%M:%S%.f").map(|d| d.date())
284	            })
285	            .or_else(|_| {
286	                NaiveDateTime::parse_from_str(&value, "%Y-%m-%d %H:%M:%S%.f").map(|d| d.date())
287	            })
288	            .map_err(serde::de::Error::custom)?;
289	        Ok(Self(date))
