  1	//! PostgreSQL reconciliation of one complete, prevalidated Commons refresh.
  2	use crate::domain::{
  3	    models::member_ingestion::{MemberImport, MemberImportSummary, MemberRecord, MemberRefresh},
  4	    repositories::member_writer::{MemberWriteError, MemberWriter},
  5	};
  6	use anyhow::{Context, ensure};
  7	use chrono::{DateTime, NaiveDate, Utc};
  8	use sqlx::{Connection, PgConnection, Postgres, Row, Transaction, postgres::PgConnectOptions};
  9	use std::{str::FromStr, time::Duration};
 10	use uuid::Uuid;
 11	
 12	/// Offline member writer; construction validates configuration without connecting.
 13	#[derive(Clone)]
 14	pub struct MemberDatabase {
 15	    options: PgConnectOptions,
 16	}
 17	impl MemberDatabase {
 18	    /// Store validated connection settings for a later atomic refresh.
 19	    ///
 20	    /// # Errors
 21	    /// Rejects an empty or invalid PostgreSQL connection string.
 22	    pub fn new(connection_string: &str) -> Result<Self, MemberWriteError> {
 23	        if connection_string.trim().is_empty() {
 24	            return Err(MemberWriteError(
 25	                "connection_string must not be empty".into(),
 26	            ));
 27	        }
 28	        let options = PgConnectOptions::from_str(connection_string)
 29	            .map_err(|_| MemberWriteError("invalid PostgreSQL connection string".into()))?
 30	            .application_name("exposed-member-load");
 31	        Ok(Self { options })
 32	    }
 33	
 34	    async fn write(&self, refresh: &MemberRefresh) -> anyhow::Result<MemberImportSummary> {
 35	        let mut connection = tokio::time::timeout(
 36	            Duration::from_secs(10),
 37	            PgConnection::connect_with(&self.options),
 38	        )
 39	        .await
 40	        .context("PostgreSQL connection timed out")?
 41	        .context("connect to PostgreSQL")?;
 42	        let mut transaction = connection.begin().await?;
 43	        let term_id = ensure_term(&mut transaction, refresh.term_start).await?;
 44	        let mut summary = MemberImportSummary {
 45	            excluded_candidates: refresh.excluded_candidates,
 46	            ..MemberImportSummary::default()
 47	        };
 48	        for import in &refresh.members {
 49	            let change = write_member(&mut transaction, term_id, import)
 50	                .await
 51	                .with_context(|| format!("member {}", import.member.parliament_member_id))?;
 52	            match change {
 53	                ProfileChange::Inserted => summary.inserted += 1,
 54	                ProfileChange::Updated => summary.updated += 1,
 55	                ProfileChange::Unchanged => summary.unchanged += 1,
 56	            }
 57	            summary.members += 1;
 58	            if import.member.is_current_commons {
 59	                summary.current_commons += 1;
 60	            } else {
 61	                summary.former_commons += 1;
 62	            }
 63	            summary.service_periods += import.periods.len();
 64	        }
 65	        transaction
 66	            .commit()
 67	            .await
 68	            .context("commit member refresh")?;
 69	        Ok(summary)
 70	    }
 71	}
 72	impl MemberWriter for MemberDatabase {
 73	    async fn refresh_members(
 74	        &self,
 75	        refresh: &MemberRefresh,
 76	    ) -> Result<MemberImportSummary, MemberWriteError> {
 77	        self.write(refresh)
 78	            .await
 79	            .map_err(|error| MemberWriteError(format!("{error:#}")))
 80	    }
 81	}
 82	
 83	enum ProfileChange {
 84	    Inserted,
 85	    Updated,
 86	    Unchanged,
 87	}
 88	
 89	const fn midnight(date: NaiveDate) -> DateTime<Utc> {
 90	    date.and_time(chrono::NaiveTime::MIN).and_utc()
 91	}
 92	
 93	async fn ensure_term(
 94	    transaction: &mut Transaction<'_, Postgres>,
 95	    start: NaiveDate,
 96	) -> anyhow::Result<Uuid> {
 97	    let terms: Vec<(Uuid, DateTime<Utc>)> =
 98	        sqlx::query_as("SELECT id, term_start FROM exposed.parliament_terms")
 99	            .fetch_all(&mut **transaction)
100	            .await?;
101	    ensure!(
102	        terms.iter().all(|(_, date)| *date == midnight(start)),
103	        "database contains another term; this operation refreshes one configured Parliament"
104	    );
105	    if let Some((id, _)) = terms.first() {
106	        return Ok(*id);
107	    }
108	    let id = sqlx::query_scalar(
109	        "INSERT INTO exposed.parliament_terms (id, term_start) VALUES ($1, $2) RETURNING id",
110	    )
111	    .bind(Uuid::now_v7())
112	    .bind(midnight(start))
113	    .fetch_one(&mut **transaction)
114	    .await?;
115	    Ok(id)
116	}
117	
118	async fn write_member(
119	    transaction: &mut Transaction<'_, Postgres>,
120	    term_id: Uuid,
121	    import: &MemberImport,
122	) -> anyhow::Result<ProfileChange> {
123	    let member = &import.member;
124	    let previous = sqlx::query("SELECT parliament_member_id, name, party_id, party_name, latest_house, latest_membership_from, is_current_commons FROM exposed.members WHERE parliament_member_id = $1")
125	        .bind(member.parliament_member_id).fetch_optional(&mut **transaction).await?;
126	    let change = if let Some(row) = previous {
127	        let stored = MemberRecord {
128	            parliament_member_id: row.try_get("parliament_member_id")?,
129	            name: row.try_get("name")?,
130	            party_id: row.try_get("party_id")?,
131	            party_name: row.try_get("party_name")?,
132	            latest_house: row.try_get("latest_house")?,
133	            latest_membership_from: row.try_get("latest_membership_from")?,
134	            is_current_commons: row.try_get("is_current_commons")?,
135	        };
136	        if stored == *member {
137	            ProfileChange::Unchanged
138	        } else {
139	            ProfileChange::Updated
140	        }
141	    } else {
142	        ProfileChange::Inserted
143	    };
144	    let member_id: Uuid = sqlx::query_scalar(
145	        "INSERT INTO exposed.members (id, parliament_member_id, name, party_id, party_name, latest_house, latest_membership_from, is_current_commons)
146	         VALUES ($1, $2, $3, $4, $5, $6, $7, $8)
147	         ON CONFLICT (parliament_member_id) DO UPDATE SET name = EXCLUDED.name,
148	           party_id = EXCLUDED.party_id, party_name = EXCLUDED.party_name,
149	           latest_house = EXCLUDED.latest_house, latest_membership_from = EXCLUDED.latest_membership_from,
150	           is_current_commons = EXCLUDED.is_current_commons RETURNING id")
151	        .bind(Uuid::now_v7()).bind(member.parliament_member_id).bind(&member.name).bind(member.party_id)
152	        .bind(&member.party_name).bind(member.latest_house).bind(&member.latest_membership_from).bind(member.is_current_commons)
153	        .fetch_one(&mut **transaction).await?;
154	    for period in &import.periods {
155	        sqlx::query(
156	            "INSERT INTO exposed.member_terms (id, member_id, term_id, house, source_start_date, source_end_date, served_from, served_until)
157	             VALUES ($1, $2, $3, 1, $4, $5, $6, $5)
158	             ON CONFLICT (member_id, term_id, house, source_start_date) DO UPDATE SET
159	                source_end_date = EXCLUDED.source_end_date, served_from = EXCLUDED.served_from, served_until = EXCLUDED.served_until")
160	            .bind(Uuid::now_v7()).bind(member_id).bind(term_id).bind(midnight(period.source_start_date))
161	            .bind(period.source_end_date.map(midnight)).bind(midnight(period.served_from)).execute(&mut **transaction).await?;
162	    }
163	    let starts: Vec<_> = import
164	        .periods
165	        .iter()
166	        .map(|p| midnight(p.source_start_date))
167	        .collect();
168	    sqlx::query("DELETE FROM exposed.member_terms WHERE member_id = $1 AND term_id = $2 AND (house <> 1 OR NOT (source_start_date = ANY($3)))")
169	        .bind(member_id).bind(term_id).bind(starts).execute(&mut **transaction).await?;
170	    Ok(change)
171	}

