157	             VALUES ($1, $2, $3, 1, $4, $5, $6, $5)
158	             ON CONFLICT (member_id, term_id, house, source_start_date) DO UPDATE SET
159	                source_end_date = EXCLUDED.source_end_date, served_from = EXCLUDED.served_from, served_until = EXCLUDED.served_until")
160	            .bind(Uuid::now_v7()).bind(member_id).bind(term_id).bind(midnight(period.source_start_date))
161	            .bind(period.source_end_date.map(midnight)).bind(midnight(period.served_from)).execute(&mut **transaction).await?;
162	    }
163	    let starts: Vec<_> = import
164	        .periods
165	        .iter()
166	        .map(|p| midnight(p.source_start_date))
167	        .collect();
168	    sqlx::query("DELETE FROM exposed.member_terms WHERE member_id = $1 AND term_id = $2 AND (house <> 1 OR NOT (source_start_date = ANY($3)))")
169	        .bind(member_id).bind(term_id).bind(starts).execute(&mut **transaction).await?;
170	    Ok(change)
171	}

