  1	//! Captured member observations and the rules for interpreting Commons service.
  2	
  3	use std::{
  4	    collections::{BTreeMap, BTreeSet},
  5	    fmt,
  6	    str::FromStr,
  7	};
  8	
  9	use chrono::{DateTime, NaiveDate, Utc};
 10	use serde::{Deserialize, Serialize};
 11	use uuid::Uuid;
 12	
 13	use super::entity_ingestion::EntityIngestionError;
 14	
 15	/// Identity of an immutable capture, ordered by `UUIDv7` creation time.
 16	#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Serialize, Deserialize)]
 17	#[serde(try_from = "Uuid", into = "Uuid")]
 18	pub struct CaptureId(Uuid);
 19	
 20	impl CaptureId {
 21	    /// Allocate an identity at the beginning of a fetch attempt.
 22	    #[must_use]
 23	    pub fn new() -> Self {
 24	        Self(Uuid::now_v7())
 25	    }
 26	}
 27	
 28	impl Default for CaptureId {
 29	    fn default() -> Self {
 30	        Self::new()
 31	    }
 32	}
 33	impl From<CaptureId> for Uuid {
 34	    fn from(id: CaptureId) -> Self {
 35	        id.0
 36	    }
 37	}
 38	impl TryFrom<Uuid> for CaptureId {
 39	    type Error = EntityIngestionError;
 40	    fn try_from(id: Uuid) -> Result<Self, Self::Error> {
 41	        if id.get_version_num() != 7 || id.get_variant() != uuid::Variant::RFC4122 {
 42	            return Err(invalid("capture ID must be a UUIDv7"));
 43	        }
 44	        Ok(Self(id))
 45	    }
 46	}
 47	impl FromStr for CaptureId {
 48	    type Err = EntityIngestionError;
 49	    fn from_str(value: &str) -> Result<Self, Self::Err> {
 50	        Uuid::parse_str(value)
 51	            .map_err(|_| invalid("capture ID must be a UUIDv7"))?
 52	            .try_into()
 53	    }
 54	}
 55	impl fmt::Display for CaptureId {
 56	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
 57	        self.0.fmt(f)
 58	    }
 59	}
 60	
 61	/// Context fixed when acquisition begins, retained for offline interpretation.
 62	#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
 63	pub struct CaptureContext {
 64	    /// `UUIDv7` allocated for this attempt.
 65	    pub capture_id: CaptureId,
 66	    /// Beginning of the configured Parliament.
 67	    pub term_start: NaiveDate,
 68	    /// Calendar date in Europe/London at the start of acquisition.
 69	    pub observation_date: NaiveDate,
 70	    /// UTC instant at the start of acquisition.
 71	    pub started_at: DateTime<Utc>,
 72	}
 73	
 74	/// Historical candidate profile; optional source values remain absent.
 75	#[derive(Clone, Debug, PartialEq, Eq)]
 76	pub struct MemberProfile {
 77	    /// Parliament's numeric identity.
 78	    pub parliament_member_id: i32,
 79	    /// Source display name, without normalization.
 80	    pub name: String,
 81	    /// Latest party identity when supplied.
 82	    pub party_id: Option<i32>,
 83	    /// Latest party name when supplied.
 84	    pub party_name: Option<String>,
 85	    /// Latest House, which may be Lords for a former MP.
 86	    pub latest_house: i16,
 87	    /// Latest membership location when supplied.
 88	    pub latest_membership_from: Option<String>,
 89	}
 90	
 91	/// One source House membership, before any term clipping or deduplication.
 92	#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]
 93	pub struct HouseMembership {
 94	    /// Commons (1) or Lords (2).
 95	    pub house: i16,
 96	    /// Source calendar start date.
 97	    pub start_date: NaiveDate,
 98	    /// Date service ceased, if supplied.
 99	    pub end_date: Option<NaiveDate>,
100	}
101	
102	/// A returned history, retaining its identity for completeness checks.
103	#[derive(Clone, Debug, PartialEq, Eq)]
104	pub struct MemberHistory {
105	    /// Parliament's numeric identity.
106	    pub parliament_member_id: i32,
107	    /// All returned House membership periods, including identical repeats.
108	    pub house_memberships: Vec<HouseMembership>,
109	}
110	
111	/// Complete source observations, with no database identities or derived service.
112	#[derive(Clone, Debug, PartialEq, Eq)]
113	pub struct MemberObservations {
114	    /// Distinct historical candidate profiles.
115	    pub profiles: Vec<MemberProfile>,
116	    /// Distinct identities observed in the current Commons search.
117	    pub current_commons: Vec<i32>,
118	    /// Exactly one history for every candidate.
119	    pub histories: Vec<MemberHistory>,
120	}
121	
122	/// A member capture ready to persist or interpret.
123	#[derive(Clone, Debug, PartialEq, Eq)]
124	pub struct MemberCapture {
125	    /// Original term and observation context.
126	    pub context: CaptureContext,
127	    /// Complete source observations.
128	    pub observations: MemberObservations,
129	}
130	
131	/// Row counts for the three raw datasets.
132	#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
133	pub struct CaptureCounts {
134	    /// Historical candidate profiles.
135	    pub profiles: usize,
136	    /// Current Commons identities.
137	    pub current_commons: usize,
138	    /// All source House membership periods.
139	    pub house_memberships: usize,
140	}
141	
142	impl MemberObservations {
143	    /// Counts before service filtering and deduplication.
144	    #[must_use]
145	    pub fn counts(&self) -> CaptureCounts {
146	        CaptureCounts {
147	            profiles: self.profiles.len(),
148	            current_commons: self.current_commons.len(),
149	            house_memberships: self
150	                .histories
151	                .iter()
152	                .map(|h| h.house_memberships.len())
153	                .sum(),
154	        }
155	    }
156	
157	    /// Check identities and completeness without applying service rules.
158	    ///
159	    /// # Errors
160	    /// Rejects duplicate, invalid, extra or missing source identities and empty histories.
161	    pub fn validate(&self) -> Result<(), EntityIngestionError> {
162	        let mut candidates = BTreeSet::new();
163	        for profile in &self.profiles {
164	            let id = profile.parliament_member_id;
165	            if id <= 0 || !candidates.insert(id) {
166	                return Err(invalid(format!(
167	                    "member {id}: invalid or duplicate profile identity"
168	                )));
169	            }
170	        }
171	        let mut current = BTreeSet::new();
172	        for id in &self.current_commons {
173	            if !current.insert(*id) || !candidates.contains(id) {
174	                return Err(invalid(format!(
175	                    "current Commons member {id}: duplicate or missing from historical candidates"
176	                )));
177	            }
178	        }
179	        let mut histories = BTreeSet::new();
180	        for history in &self.histories {
181	            let id = history.parliament_member_id;
182	            if !histories.insert(id)
183	                || !candidates.contains(&id)
184	                || history.house_memberships.is_empty()
185	            {
186	                return Err(invalid(format!(
187	                    "member {id}: duplicate, unexpected or empty history"
188	                )));
189	            }
190	        }
191	        if histories != candidates {
192	            return Err(invalid("histories do not contain all requested member IDs"));
193	        }
194	        Ok(())
195	    }
196	}
197	
198	/// Validated member fields for PostgreSQL.
199	#[derive(Clone, Debug, PartialEq, Eq)]
200	pub struct MemberRecord {
201	    /// Parliament's numeric identity, used for reconciliation.
202	    pub parliament_member_id: i32,
203	    /// Source display name.
204	    pub name: String,
205	    /// Required latest party identity.
206	    pub party_id: i32,
207	    /// Required latest party name.
208	    pub party_name: String,
209	    /// Latest House from the historical candidate profile.
210	    pub latest_house: i16,
211	    /// Required latest membership location.
212	    pub latest_membership_from: String,
213	    /// Status from the captured current Commons search.
214	    pub is_current_commons: bool,
215	}
216	
217	/// A distinct Commons interval in the configured term.
218	#[derive(Clone, Debug, PartialEq, Eq)]
219	pub struct ServicePeriod {
220	    /// Source start date, the stable identity of an interval.
221	    pub source_start_date: NaiveDate,
222	    /// Source end date, also used as served-until.
223	    pub source_end_date: Option<NaiveDate>,
224	    /// Later of source start and term start.
225	    pub served_from: NaiveDate,
226	}
227	
228	/// One accepted profile and its complete replacement set of term service.
229	#[derive(Clone, Debug)]
230	pub struct MemberImport {
231	    /// Validated profile to reconcile.
232	    pub member: MemberRecord,
233	    /// Distinct and non-overlapping Commons periods.
234	    pub periods: Vec<ServicePeriod>,
235	}
236	
237	/// Entire refresh validated before storage receives it.
238	#[derive(Clone, Debug)]
239	pub struct MemberRefresh {
240	    /// Captured Parliament start.
241	    pub term_start: NaiveDate,
242	    /// Eligible members; absent members must remain untouched.
243	    pub members: Vec<MemberImport>,
244	    /// Candidates with no qualifying Commons service.
245	    pub excluded_candidates: usize,
246	}
247	
248	/// Committed profile outcomes and cohort/service counts.
249	#[derive(Clone, Debug, Default, Serialize)]
250	pub struct MemberImportSummary {
251	    /// Number of eligible members processed.
252	    pub members: usize,
253	    /// Current Commons members.
254	    pub current_commons: usize,
255	    /// Former Commons members.
256	    pub former_commons: usize,
257	    /// Newly inserted profiles.
258	    pub inserted: usize,
259	    /// Changed profiles.
260	    pub updated: usize,
261	    /// Identical profiles.
262	    pub unchanged: usize,
263	    /// Distinct term service periods reconciled.
264	    pub service_periods: usize,
265	    /// Candidates excluded for lack of term service.
266	    pub excluded_candidates: usize,
267	}
268	
269	impl MemberCapture {
270	    /// Interpret all observations before making any database writes.
271	    ///
272	    /// # Errors
273	    /// Rejects incomplete captures, invalid fields and inconsistent Commons service.
274	    pub fn prepare_refresh(&self) -> Result<MemberRefresh, EntityIngestionError> {
275	        self.observations.validate()?;
276	        let term_start = self.context.term_start;
277	        let as_of = self.context.observation_date;
278	        if term_start > as_of {
279	            return Err(invalid("term start is after observation date"));
280	        }
281	        let current: BTreeSet<_> = self.observations.current_commons.iter().copied().collect();
282	        let histories: BTreeMap<_, _> = self
283	            .observations
284	            .histories
285	            .iter()
286	            .map(|h| (h.parliament_member_id, h))
287	            .collect();
288	        let mut refresh = MemberRefresh {
289	            term_start,
290	            members: Vec::new(),
291	            excluded_candidates: 0,
292	        };
293	        for profile in &self.observations.profiles {
294	            let id = profile.parliament_member_id;
295	            let is_current = current.contains(&id);
296	            let periods = service_periods(histories[&id], term_start, as_of, is_current)?;
297	            if periods.is_empty() {
298	                refresh.excluded_candidates += 1;
299	                continue;
300	            }
301	            let member = profile.for_database(is_current)?;
302	            refresh.members.push(MemberImport { member, periods });
303	        }
304	        if refresh.members.is_empty() {
305	            return Err(invalid(
306	                "no Commons service was found for the configured term",
307	            ));
308	        }
309	        Ok(refresh)
310	    }
311	}
312	
313	impl MemberProfile {
314	    fn for_database(&self, is_current_commons: bool) -> Result<MemberRecord, EntityIngestionError> {
315	        let id = self.parliament_member_id;
316	        let required =
317	            |field: &str| invalid(format!("member {id}: {field} is required for PostgreSQL"));
318	        if self.name.trim().is_empty() {
319	            return Err(required("name"));
320	        }
321	        if !matches!(self.latest_house, 1 | 2) || (is_current_commons && self.latest_house != 1) {
322	            return Err(invalid(format!("member {id}: inconsistent latest House")));
323	        }
324	        Ok(MemberRecord {
325	            parliament_member_id: id,
326	            name: self.name.clone(),
327	            party_id: self
328	                .party_id
329	                .filter(|id| *id > 0)
330	                .ok_or_else(|| required("party_id"))?,
331	            party_name: self
332	                .party_name
333	                .clone()
334	                .ok_or_else(|| required("party_name"))?,
335	            latest_house: self.latest_house,
336	            latest_membership_from: self
337	                .latest_membership_from
338	                .clone()
339	                .ok_or_else(|| required("latest_membership_from"))?,
340	            is_current_commons,
341	        })
342	    }
343	}
344	
345	fn service_periods(
346	    history: &MemberHistory,
347	    term_start: NaiveDate,
348	    as_of: NaiveDate,
349	    current: bool,
350	) -> Result<Vec<ServicePeriod>, EntityIngestionError> {
351	    let id = history.parliament_member_id;
352	    let mut memberships = BTreeSet::new();
353	    for membership in &history.house_memberships {
354	        if !matches!(membership.house, 1 | 2)
355	            || membership
356	                .end_date
357	                .is_some_and(|end| end < membership.start_date)
358	        {
359	            return Err(invalid(format!(
360	                "member {id}: invalid House or membership date ordering"
361	            )));
362	        }
363	        if membership.house == 1
364	            && membership.start_date <= as_of
365	            && membership.end_date.is_none_or(|end| end > term_start)
366	        {
367	            memberships.insert(membership);
368	        }
369	    }
370	    let periods: Vec<_> = memberships
371	        .into_iter()
372	        .map(|m| ServicePeriod {
373	            source_start_date: m.start_date,
374	            source_end_date: m.end_date,
375	            served_from: m.start_date.max(term_start),
376	        })
377	        .collect();
378	    for pair in periods.windows(2) {
379	        if pair[0].source_start_date == pair[1].source_start_date {
380	            return Err(invalid(format!("member {id}: conflicting service starts")));
381	        }
382	        if pair[0]
383	            .source_end_date
384	            .is_none_or(|end| pair[1].served_from < end)
385	        {
386	            return Err(invalid(format!("member {id}: overlapping service periods")));
387	        }
388	    }
389	    let active = periods
390	        .iter()
391	        .any(|p| p.source_end_date.is_none_or(|end| end > as_of));
392	    if active != current {
393	        return Err(invalid(format!(
394	            "member {id}: history disagrees with current Commons search"
395	        )));
396	    }
397	    Ok(periods)
398	}
399	
400	pub(crate) fn invalid(message: impl Into<String>) -> EntityIngestionError {
401	    EntityIngestionError::DataError(message.into())
402	}

