160	    /// Rejects duplicate, invalid, extra or missing source identities and empty histories.
161	    pub fn validate(&self) -> Result<(), EntityIngestionError> {
162	        let mut candidates = BTreeSet::new();
163	        for profile in &self.profiles {
164	            let id = profile.parliament_member_id;
165	            if id <= 0 || !candidates.insert(id) {
166	                return Err(invalid(format!(
167	                    "member {id}: invalid or duplicate profile identity"
168	                )));
169	            }
170	        }
171	        let mut current = BTreeSet::new();
172	        for id in &self.current_commons {
173	            if !current.insert(*id) || !candidates.contains(id) {
174	                return Err(invalid(format!(
175	                    "current Commons member {id}: duplicate or missing from historical candidates"
176	                )));
177	            }
178	        }
179	        let mut histories = BTreeSet::new();
180	        for history in &self.histories {
181	            let id = history.parliament_member_id;
182	            if !histories.insert(id)
183	                || !candidates.contains(&id)
184	                || history.house_memberships.is_empty()
185	            {
186	                return Err(invalid(format!(
187	                    "member {id}: duplicate, unexpected or empty history"
188	                )));
189	            }
190	        }
191	        if histories != candidates {
192	            return Err(invalid("histories do not contain all requested member IDs"));
193	        }
