    93	async fn ensure_term(
    94	    transaction: &mut Transaction<'_, Postgres>,
    95	    start: NaiveDate,
    96	) -> anyhow::Result<Uuid> {
    97	    let terms: Vec<(Uuid, DateTime<Utc>)> =
