   106	        return Ok(*id);
   107	    }
   108	    let id = sqlx::query_scalar(
   109	        "INSERT INTO exposed.parliament_terms (id, term_start) VALUES ($1, $2) RETURNING id",
   110	    )
   111	    .bind(Uuid::now_v7())
   112	    .bind(midnight(start))
   113	    .fetch_one(&mut **transaction)
   114	    .await?;
