  1	//! Sequential Members API requests, typed decoding and bounded retries.
  2	use crate::domain::{
  3	    models::member_ingestion::{HouseMembership, MemberHistory, MemberProfile},
  4	    repositories::parliament_api::{ParliamentApi, ParliamentApiError},
  5	};
  6	use chrono::{DateTime, NaiveDate, NaiveDateTime};
  7	use reqwest::{Client, StatusCode, Url};
  8	use serde::{Deserialize, de::DeserializeOwned};
  9	use serde_json::Value;
 10	use std::{
 11	    fmt::Display,
 12	    time::{Duration, SystemTime},
 13	};
 14	
 15	/// Production HTTP source for the Commons cohort.
 16	#[derive(Clone)]
 17	pub struct MembersApi {
 18	    client: Client,
 19	    base_url: Url,
 20	}
 21	impl MembersApi {
 22	    /// Build an HTTP client without issuing requests.
 23	    ///
 24	    /// # Errors
 25	    /// Rejects invalid URLs or HTTP client configuration.
 26	    pub fn new(base_url: &str) -> Result<Self, ParliamentApiError> {
 27	        let base_url = Url::parse(base_url).map_err(|_| failure("invalid Members API URL"))?;
 28	        if !matches!(base_url.scheme(), "http" | "https")
 29	            || base_url.host_str().is_none()
 30	            || !base_url.username().is_empty()
 31	            || base_url.password().is_some()
 32	        {
 33	            return Err(failure(
 34	                "Members API URL must be an HTTP(S) URL without credentials",
 35	            ));
 36	        }
 37	        let client = Client::builder()
 38	            .connect_timeout(Duration::from_secs(10))
 39	            .timeout(Duration::from_secs(30))
 40	            .build()
 41	            .map_err(failure)?;
 42	        Ok(Self { client, base_url })
 43	    }
 44	
 45	    async fn get(
 46	        &self,
 47	        path: &str,
 48	        params: &[(&str, String)],
 49	    ) -> Result<Vec<u8>, ParliamentApiError> {
 50	        let mut url = self.base_url.join(path).map_err(failure)?;
 51	        url.query_pairs_mut()
 52	            .extend_pairs(params.iter().map(|(key, value)| (*key, value.as_str())));
 53	        // Request context contains source filters/IDs, never connection credentials.
 54	        let context = format!("{path}?{}", url.query().unwrap_or_default());
 55	        for attempt in 0..4 {
 56	            tokio::time::sleep(Duration::from_millis(200)).await;
 57	            let mut delay = Duration::from_secs(1 << attempt);
 58	            let problem = match self.client.get(url.clone()).send().await {
 59	                Ok(response) => {
 60	                    let status = response.status();
 61	                    if status == StatusCode::OK {
 62	                        match response.bytes().await {
 63	                            Ok(bytes) => return Ok(bytes.to_vec()),
 64	                            Err(error) => format!("response transport failure: {error}"),
 65	                        }
 66	                    } else {
 67	                        if status != StatusCode::TOO_MANY_REQUESTS && !status.is_server_error() {
 68	                            return Err(failure(format!("{context}: HTTP {status}")));
 69	                        }
 70	                        if let Some(header) = response
 71	                            .headers()
 72	                            .get(reqwest::header::RETRY_AFTER)
 73	                            .and_then(|h| h.to_str().ok())
 74	                        {
 75	                            delay = retry_delay(header).unwrap_or(delay);
 76	                        }
 77	                        format!("HTTP {status}")
 78	                    }
 79	                }
 80	                Err(error) => format!("transport failure: {error}"),
 81	            };
 82	            if attempt == 3 {
 83	                return Err(failure(format!("{context}: {problem} after four attempts")));
 84	            }
 85	            eprintln!("{context}: {problem}; retry {}/4", attempt + 2);
 86	            tokio::time::sleep(delay.min(Duration::from_secs(30))).await;
 87	        }
 88	        unreachable!("four attempts always return success or failure")
 89	    }
 90	
 91	    async fn search(
 92	        &self,
 93	        filters: Vec<(&str, String)>,
 94	    ) -> Result<Vec<MemberProfile>, ParliamentApiError> {
 95	        let mut profiles = Vec::new();
 96	        let mut offset = 0;
 97	        loop {
 98	            let mut params = filters.clone();
 99	            params.extend([("skip", offset.to_string()), ("take", "20".to_owned())]);
100	            let bytes = self.get("/api/Members/Search", &params).await?;
101	            let context = format!("/api/Members/Search {params:?}");
102	            let page: SearchPage = decode(&bytes, &context)?;
103	            if page.skip != offset {
104	                return Err(failure(format!(
105	                    "{context}: response skip {} does not match request {offset}",
106	                    page.skip
107	                )));
108	            }
109	            if page.items.is_empty() && offset < page.total_results {
110	                return Err(failure(format!(
111	                    "{context}: premature empty page before total {}",
112	                    page.total_results
113	                )));
114	            }
115	            offset = offset
116	                .checked_add(page.items.len())
117	                .ok_or_else(|| failure("search pagination overflow"))?;
118	            for value in page.items {
119	                let item: Item<Profile> = decode_item(value, &context)?;
120	                profiles.push(MemberProfile {
121	                    parliament_member_id: item.value.id,
122	                    name: item.value.name_display_as,
123	                    party_id: item.value.latest_party.as_ref().and_then(|p| p.id),
