  1	//! Immutable member captures, staged and published on the same filesystem.
  2	use super::member_parquet;
  3	use crate::domain::{
  4	    models::member_ingestion::{CaptureContext, CaptureCounts, CaptureId, MemberCapture},
  5	    repositories::entity_ingestion_pipline::{EntityIngestionStorage, EntitySearchPipelineError},
  6	};
  7	use anyhow::{Context, ensure};
  8	use chrono::{DateTime, Utc};
  9	use serde::{Deserialize, Serialize};
 10	use std::{
 11	    fs::{self, File},
 12	    path::{Path, PathBuf},
 13	};
 14	
 15	/// Local data root with captures at raw/members/<UUIDv7>.
 16	#[derive(Clone)]
 17	pub struct ExposedDataPipeline {
 18	    root: PathBuf,
 19	}
 20	impl ExposedDataPipeline {
 21	    /// Use this data root without creating files until Fetch is finalized.
 22	    #[must_use]
 23	    pub const fn new(root: PathBuf) -> Self {
 24	        Self { root }
 25	    }
 26	
 27	    fn read_at(path: &Path, id: CaptureId) -> anyhow::Result<MemberCapture> {
 28	        let manifest: Manifest = serde_json::from_reader(
 29	            File::open(path.join("manifest.json")).context("missing completed manifest")?,
 30	        )
 31	        .context("invalid manifest")?;
 32	        ensure!(
 33	            manifest.schema_version == 1,
 34	            "unsupported member schema version {}",
 35	            manifest.schema_version
 36	        );
 37	        ensure!(
 38	            manifest.context.capture_id == id,
 39	            "manifest capture identity does not match {id}"
 40	        );
 41	        ensure!(
 42	            manifest.completed_at >= manifest.context.started_at,
 43	            "completion timestamp precedes capture start"
 44	        );
 45	        ensure!(
 46	            manifest.context.term_start <= manifest.context.observation_date,
 47	            "term starts after observation date"
 48	        );
 49	        ensure!(
 50	            manifest.datasets == DatasetFiles::default(),
 51	            "manifest must identify all three schema-v1 datasets"
 52	        );
 53	        let observations = member_parquet::read(path)?;
 54	        ensure!(
 55	            observations.counts() == manifest.counts,
 56	            "dataset row counts disagree with manifest"
 57	        );
 58	        observations.validate()?;
 59	        Ok(MemberCapture {
 60	            context: manifest.context,
 61	            observations,
 62	        })
 63	    }
 64	
 65	    fn stage(&self, capture: &MemberCapture) -> anyhow::Result<PendingCapture> {
 66	        capture.observations.validate()?;
 67	        let id = capture.context.capture_id;
 68	        let parent = self.root.join("raw/members");
 69	        fs::create_dir_all(&parent)?;
 70	        let destination = parent.join(id.to_string());
 71	        ensure!(
 72	            !destination.exists(),
 73	            "completed capture {id} already exists"
 74	        );
 75	        let staging = tempfile::Builder::new()
 76	            .prefix(&format!(".staging-{id}-"))
 77	            .tempdir_in(&parent)?;
 78	        member_parquet::write(staging.path(), &capture.observations)?;
 79	        let manifest = Manifest {
 80	            schema_version: 1,
 81	            context: capture.context.clone(),
 82	            completed_at: Utc::now(),
 83	            datasets: DatasetFiles::default(),
 84	            counts: capture.observations.counts(),
 85	        };
 86	        let file = File::create_new(staging.path().join("manifest.json"))?;
 87	        serde_json::to_writer_pretty(&file, &manifest)?;
 88	        file.sync_all()?;
 89	        let verified = Self::read_at(staging.path(), id)?;
 90	        ensure!(
 91	            verified == *capture,
 92	            "capture round-trip verification failed"
 93	        );
 94	        Ok(PendingCapture {
 95	            staging,
 96	            destination,
 97	            id,
 98	        })
 99	    }
100	}
101	impl EntityIngestionStorage for ExposedDataPipeline {
102	    async fn read_member_capture(
103	        &self,
104	        id: CaptureId,
105	    ) -> Result<MemberCapture, EntitySearchPipelineError> {
106	        let path = self.root.join("raw/members").join(id.to_string());
