  1	//! Schema-v1 Parquet translation. Domain rules are applied only after reading.
  2	use crate::domain::models::member_ingestion::{
  3	    HouseMembership, MemberHistory, MemberObservations, MemberProfile,
  4	};
  5	use anyhow::{Context, ensure};
  6	use arrow_array::{Array, ArrayRef, Date32Array, Int16Array, Int32Array, RecordBatch, StringArray};
  7	use arrow_schema::{DataType, Field, Schema, SchemaRef};
  8	use chrono::NaiveDate;
  9	use parquet::{
 10	    arrow::{ArrowWriter, arrow_reader::ParquetRecordBatchReaderBuilder},
 11	    basic::Compression,
 12	    file::properties::WriterProperties,
 13	};
 14	use std::{collections::BTreeMap, fs::File, path::Path, sync::Arc};
 15	
 16	fn profiles_schema() -> SchemaRef {
 17	    Arc::new(Schema::new(vec![
 18	        Field::new("parliament_member_id", DataType::Int32, false),
 19	        Field::new("name", DataType::Utf8, false),
 20	        Field::new("party_id", DataType::Int32, true),
 21	        Field::new("party_name", DataType::Utf8, true),
 22	        Field::new("latest_house", DataType::Int16, false),
 23	        Field::new("latest_membership_from", DataType::Utf8, true),
 24	    ]))
 25	}
 26	fn current_schema() -> SchemaRef {
 27	    Arc::new(Schema::new(vec![Field::new(
 28	        "parliament_member_id",
 29	        DataType::Int32,
 30	        false,
 31	    )]))
 32	}
 33	fn memberships_schema() -> SchemaRef {
 34	    Arc::new(Schema::new(vec![
 35	        Field::new("parliament_member_id", DataType::Int32, false),
 36	        Field::new("house", DataType::Int16, false),
 37	        Field::new("source_start_date", DataType::Date32, false),
 38	        Field::new("source_end_date", DataType::Date32, true),
 39	    ]))
 40	}
 41	
 42	pub(super) fn write(path: &Path, data: &MemberObservations) -> anyhow::Result<()> {
 43	    let profiles = &data.profiles;
 44	    write_batch(
 45	        &path.join("profiles.parquet"),
 46	        profiles_schema(),
 47	        vec![
 48	            Arc::new(Int32Array::from_iter_values(
 49	                profiles.iter().map(|p| p.parliament_member_id),
 50	            )),
 51	            Arc::new(StringArray::from_iter_values(
 52	                profiles.iter().map(|p| &p.name),
 53	            )),
 54	            Arc::new(Int32Array::from_iter(profiles.iter().map(|p| p.party_id))),
 55	            Arc::new(StringArray::from_iter(
 56	                profiles.iter().map(|p| p.party_name.as_deref()),
 57	            )),
 58	            Arc::new(Int16Array::from_iter_values(
 59	                profiles.iter().map(|p| p.latest_house),
 60	            )),
 61	            Arc::new(StringArray::from_iter(
 62	                profiles.iter().map(|p| p.latest_membership_from.as_deref()),
 63	            )),
 64	        ],
 65	    )?;
 66	    write_batch(
 67	        &path.join("current_commons.parquet"),
 68	        current_schema(),
 69	        vec![Arc::new(Int32Array::from(data.current_commons.clone()))],
 70	    )?;
 71	    let rows: Vec<_> = data
 72	        .histories
 73	        .iter()
 74	        .flat_map(|h| {
 75	            h.house_memberships
 76	                .iter()
 77	                .map(move |m| (h.parliament_member_id, m))
 78	        })
 79	        .collect();
 80	    write_batch(
 81	        &path.join("house_memberships.parquet"),
 82	        memberships_schema(),
 83	        vec![
 84	            Arc::new(Int32Array::from_iter_values(rows.iter().map(|(id, _)| *id))),
 85	            Arc::new(Int16Array::from_iter_values(
 86	                rows.iter().map(|(_, m)| m.house),
 87	            )),
 88	            Arc::new(Date32Array::from_iter_values(
 89	                rows.iter().map(|(_, m)| m.start_date.to_epoch_days()),
 90	            )),
 91	            Arc::new(Date32Array::from_iter(
 92	                rows.iter()
 93	                    .map(|(_, m)| m.end_date.map(|d| d.to_epoch_days())),
 94	            )),
 95	        ],
 96	    )?;
 97	    Ok(())
 98	}
 99	fn write_batch(path: &Path, schema: SchemaRef, columns: Vec<ArrayRef>) -> anyhow::Result<()> {
100	    let batch = RecordBatch::try_new(schema.clone(), columns)?;
101	    let file = File::create_new(path).with_context(|| format!("create {}", path.display()))?;
102	    let properties = WriterProperties::builder()
103	        .set_compression(Compression::SNAPPY)
104	        .build();
105	    let mut writer = ArrowWriter::try_new(&file, schema, Some(properties))?;
106	    writer.write(&batch)?;
107	    writer.close()?;
108	    file.sync_all()?;
109	    Ok(())
110	}
111	
112	pub(super) fn read(path: &Path) -> anyhow::Result<MemberObservations> {
113	    let mut profiles = Vec::new();
114	    for batch in read_batches(&path.join("profiles.parquet"), &profiles_schema())? {
115	        let ids: &Int32Array = column(&batch, 0)?;
116	        let names: &StringArray = column(&batch, 1)?;
117	        let parties: &Int32Array = column(&batch, 2)?;
118	        let party_names: &StringArray = column(&batch, 3)?;
119	        let houses: &Int16Array = column(&batch, 4)?;
120	        let locations: &StringArray = column(&batch, 5)?;
121	        for row in 0..batch.num_rows() {
122	            profiles.push(MemberProfile {
123	                parliament_member_id: ids.value(row),
124	                name: names.value(row).into(),
125	                party_id: (!parties.is_null(row)).then(|| parties.value(row)),
126	                party_name: (!party_names.is_null(row)).then(|| party_names.value(row).into()),
127	                latest_house: houses.value(row),
128	                latest_membership_from: (!locations.is_null(row))
129	                    .then(|| locations.value(row).into()),
130	            });
131	        }
132	    }
133	    let mut current_commons = Vec::new();
134	    for batch in read_batches(&path.join("current_commons.parquet"), &current_schema())? {
135	        let ids: &Int32Array = column(&batch, 0)?;
136	        current_commons.extend(ids.values());
137	    }
138	    let mut histories: BTreeMap<i32, Vec<HouseMembership>> = BTreeMap::new();
139	    for batch in read_batches(
140	        &path.join("house_memberships.parquet"),
141	        &memberships_schema(),
142	    )? {
143	        let ids: &Int32Array = column(&batch, 0)?;
144	        let houses: &Int16Array = column(&batch, 1)?;
145	        let starts: &Date32Array = column(&batch, 2)?;
146	        let ends: &Date32Array = column(&batch, 3)?;
147	        for row in 0..batch.num_rows() {
148	            let id = ids.value(row);
149	            let date = |value| {
150	                NaiveDate::from_epoch_days(value)
151	                    .with_context(|| format!("member {id}: invalid source calendar date"))
152	            };
153	            histories.entry(id).or_default().push(HouseMembership {
154	                house: houses.value(row),
155	                start_date: date(starts.value(row))?,
156	                end_date: if ends.is_null(row) {
157	                    None
158	                } else {
159	                    Some(date(ends.value(row))?)
160	                },
161	            });
162	        }
163	    }
164	    Ok(MemberObservations {
165	        profiles,
166	        current_commons,
167	        histories: histories
168	            .into_iter()
169	            .map(|(parliament_member_id, house_memberships)| MemberHistory {
170	                parliament_member_id,
171	                house_memberships,
172	            })
173	            .collect(),
174	    })
175	}
176	fn read_batches(path: &Path, schema: &SchemaRef) -> anyhow::Result<Vec<RecordBatch>> {
177	    let result = (|| {
178	        let builder = ParquetRecordBatchReaderBuilder::try_new(File::open(path)?)?;
179	        ensure!(
180	            builder.schema().fields() == schema.fields(),
181	            "Parquet types, fields or nullability do not match schema v1"
182	        );
183	        let batches = builder.build()?.collect::<Result<Vec<_>, _>>()?;
184	        for batch in &batches {
185	            for (field, column) in schema.fields().iter().zip(batch.columns()) {
186	                ensure!(
187	                    field.is_nullable() || column.null_count() == 0,
188	                    "required column {} contains nulls",
189	                    field.name()
190	                );
191	            }
192	        }
193	        Ok(batches)
194	    })();
195	    result.with_context(|| format!("read {}", path.display()))
196	}
197	fn column<T: Array + 'static>(batch: &RecordBatch, index: usize) -> anyhow::Result<&T> {
198	    batch
199	        .column(index)
200	        .as_any()
201	        .downcast_ref()
202	        .context("unexpected Parquet column type")
203	}

