100	    let batch = RecordBatch::try_new(schema.clone(), columns)?;
101	    let file = File::create_new(path).with_context(|| format!("create {}", path.display()))?;
102	    let properties = WriterProperties::builder()
103	        .set_compression(Compression::SNAPPY)
104	        .build();
105	    let mut writer = ArrowWriter::try_new(&file, schema, Some(properties))?;
