112	pub(super) fn read(path: &Path) -> anyhow::Result<MemberObservations> {
113	    let mut profiles = Vec::new();
114	    for batch in read_batches(&path.join("profiles.parquet"), &profiles_schema())? {
115	        let ids: &Int32Array = column(&batch, 0)?;
116	        let names: &StringArray = column(&batch, 1)?;
117	        let parties: &Int32Array = column(&batch, 2)?;
118	        let party_names: &StringArray = column(&batch, 3)?;
119	        let houses: &Int16Array = column(&batch, 4)?;
120	        let locations: &StringArray = column(&batch, 5)?;
121	        for row in 0..batch.num_rows() {
122	            profiles.push(MemberProfile {
123	                parliament_member_id: ids.value(row),
124	                name: names.value(row).into(),
125	                party_id: (!parties.is_null(row)).then(|| parties.value(row)),
126	                party_name: (!party_names.is_null(row)).then(|| party_names.value(row).into()),
127	                latest_house: houses.value(row),
128	                latest_membership_from: (!locations.is_null(row))
129	                    .then(|| locations.value(row).into()),
130	            });
131	        }
132	    }
133	    let mut current_commons = Vec::new();
134	    for batch in read_batches(&path.join("current_commons.parquet"), &current_schema())? {
135	        let ids: &Int32Array = column(&batch, 0)?;
136	        current_commons.extend(ids.values());
137	    }
138	    let mut histories: BTreeMap<i32, Vec<HouseMembership>> = BTreeMap::new();
139	    for batch in read_batches(
140	        &path.join("house_memberships.parquet"),
141	        &memberships_schema(),
142	    )? {
143	        let ids: &Int32Array = column(&batch, 0)?;
144	        let houses: &Int16Array = column(&batch, 1)?;
145	        let starts: &Date32Array = column(&batch, 2)?;
146	        let ends: &Date32Array = column(&batch, 3)?;
147	        for row in 0..batch.num_rows() {
148	            let id = ids.value(row);
149	            let date = |value| {
150	                NaiveDate::from_epoch_days(value)
151	                    .with_context(|| format!("member {id}: invalid source calendar date"))
152	            };
153	            histories.entry(id).or_default().push(HouseMembership {
154	                house: houses.value(row),
155	                start_date: date(starts.value(row))?,
156	                end_date: if ends.is_null(row) {
157	                    None
158	                } else {
159	                    Some(date(ends.value(row))?)
160	                },
161	            });
162	        }
163	    }
164	    Ok(MemberObservations {
165	        profiles,
166	        current_commons,
167	        histories: histories
168	            .into_iter()
169	            .map(|(parliament_member_id, house_memberships)| MemberHistory {
170	                parliament_member_id,
171	                house_memberships,
172	            })
173	            .collect(),
174	    })
175	}
176	fn read_batches(path: &Path, schema: &SchemaRef) -> anyhow::Result<Vec<RecordBatch>> {
177	    let result = (|| {
178	        let builder = ParquetRecordBatchReaderBuilder::try_new(File::open(path)?)?;
179	        ensure!(
180	            builder.schema().fields() == schema.fields(),
181	            "Parquet types, fields or nullability do not match schema v1"
182	        );
183	        let batches = builder.build()?.collect::<Result<Vec<_>, _>>()?;
184	        for batch in &batches {
185	            for (field, column) in schema.fields().iter().zip(batch.columns()) {
186	                ensure!(
187	                    field.is_nullable() || column.null_count() == 0,
188	                    "required column {} contains nulls",
189	                    field.name()
190	                );
191	            }
192	        }
193	        Ok(batches)
194	    })();
195	    result.with_context(|| format!("read {}", path.display()))
196	}
197	fn column<T: Array + 'static>(batch: &RecordBatch, index: usize) -> anyhow::Result<&T> {
198	    batch
199	        .column(index)
200	        .as_any()
201	        .downcast_ref()
202	        .context("unexpected Parquet column type")
203	}

