  1	use anyhow::{Context, ensure};
  2	use chrono::Utc;
  3	use clap::{Args, Parser, Subcommand};
  4	use exposed::{
  5	    config::{Config, MemberFetchConfig, MemberLoadConfig, read_data_config},
  6	    domain::{
  7	        models::{
  8	            entity_ingestion::{
  9	                EntityIngestionOutcome, EntityIngestionRequest, MemberIngestionStage,
 10	            },
 11	            member_ingestion::CaptureId,
 12	        },
 13	        services::entity_ingestion::{
 14	            FetchService, LoadService, interface::EntitySearchIngestionService,
 15	        },
 16	    },
 17	    inbound::http::server::serve_exposed,
 18	    outbound::{ExposedDataPipeline, MemberDatabase, MembersApi},
 19	};
 20	use std::{path::PathBuf, process::ExitCode};
 21	
 22	#[derive(Parser)]
 23	struct Cli {
 24	    #[command(subcommand)]
 25	    command: Commands,
 26	}
 27	#[derive(Subcommand)]
 28	enum Commands {
 29	    Server { config: PathBuf },
 30	    Data(DataArgs),
 31	}
 32	#[derive(Args)]
 33	struct DataArgs {
 34	    #[command(subcommand)]
 35	    command: DataCommands,
 36	}
 37	#[derive(Subcommand)]
 38	enum DataCommands {
 39	    Fetch {
 40	        #[command(subcommand)]
 41	        target: FetchTarget,
 42	    },
 43	    Load {
 44	        #[command(subcommand)]
 45	        target: LoadTarget,
 46	    },
 47	    Clean {
 48	        config: PathBuf,
 49	    },
 50	    Resolve {
 51	        config: PathBuf,
 52	    },
 53	}
 54	#[derive(Subcommand)]
 55	enum FetchTarget {
 56	    Members { config: PathBuf },
 57	}
 58	#[derive(Subcommand)]
 59	enum LoadTarget {
 60	    Members {
 61	        config: PathBuf,
 62	        capture_id: CaptureId,
 63	    },
 64	}
 65	
 66	#[tokio::main]
 67	async fn main() -> ExitCode {
 68	    let args = Cli::parse();
 69	    // Dropping the operation on Ctrl-C drops an in-flight transaction. Capture
 70	    // publication is synchronous once source acquisition has finished.
 71	    tokio::select! {
 72	        result = run(args) => match result {
 73	            Ok(()) => ExitCode::SUCCESS,
 74	            Err(error) => {
 75	                let code = if error.is::<InvalidConfiguration>() { 2 } else { 1 };
 76	                eprintln!("{error:#}");
 77	                ExitCode::from(code)
 78	            }
 79	        },
 80	        _ = tokio::signal::ctrl_c() => { eprintln!("Interrupted"); ExitCode::from(130) }
 81	    }
 82	}
 83	async fn run(args: Cli) -> anyhow::Result<()> {
 84	    let outcome: EntityIngestionOutcome = match args.command {
 85	        Commands::Server { config } => {
 86	            return serve_exposed(&Config::try_from(&config)?).await;
 87	        }
 88	        Commands::Data(DataArgs {
 89	            command:
 90	                DataCommands::Fetch {
 91	                    target: FetchTarget::Members { config },
 92	                },
 93	        }) => {
 94	            let started_at = Utc::now();
 95	            let observation_date = started_at
 96	                .with_timezone(&chrono_tz::Europe::London)
 97	                .date_naive();
 98	            let config: MemberFetchConfig = read_data_config(&config)
 99	                .context(InvalidConfiguration("invalid member Fetch configuration"))?;
100	            ensure!(
101	                !config.data_root.as_os_str().is_empty(),
102	                InvalidConfiguration("data_root must not be empty")
103	            );
104	            let source = MembersApi::new(&config.members_api_url)
105	                .context(InvalidConfiguration("invalid Members API configuration"))?;
106	            let storage = ExposedDataPipeline::new(config.data_root);
107	            FetchService::new(storage, source, started_at, observation_date)
108	                .run_ingestion(&EntityIngestionRequest::new_members_request(
109	                    MemberIngestionStage::Fetch {
110	                        term_start: config.term_start,
111	                    },
112	                ))
113	                .await?
114	        }
115	        Commands::Data(DataArgs {
116	            command:
117	                DataCommands::Load {
118	                    target: LoadTarget::Members { config, capture_id },
119	                },
120	        }) => {
121	            let config: MemberLoadConfig = read_data_config(&config)
122	                .context(InvalidConfiguration("invalid member Load configuration"))?;
123	            ensure!(
124	                !config.data_root.as_os_str().is_empty(),
125	                InvalidConfiguration("data_root must not be empty")
126	            );
127	            let storage = ExposedDataPipeline::new(config.data_root);
128	            let database = MemberDatabase::new(&config.connection_string).context(
129	                InvalidConfiguration("invalid member database configuration"),
130	            )?;
131	            LoadService::new(storage, database)
132	                .run_ingestion(&EntityIngestionRequest::new_members_request(
133	                    MemberIngestionStage::Load { capture_id },
134	                ))
135	                .await?
136	        }
137	        Commands::Data(_) => {
138	            anyhow::bail!("declaration cleaning and resolution are not implemented")
139	        }
140	    };
141	    let mut summary = serde_json::to_value(outcome)?;
142	    summary["status"] = "succeeded".into();
143	    println!("{}", serde_json::to_string(&summary)?);
144	    Ok(())
145	}
146	
147	#[derive(Debug, thiserror::Error)]
148	#[error("{0}")]
149	struct InvalidConfiguration(&'static str);

