  1	//! One executable workflow against real HTTP, Parquet and PostgreSQL boundaries.
  2	
  3	use arrow_array::{Array, Date32Array, Int16Array, Int32Array, RecordBatch, StringArray};
  4	use axum::{
  5	    Json, Router,
  6	    extract::{RawQuery, State},
  7	    http::StatusCode,
  8	    response::{IntoResponse, Response},
  9	    routing::get,
 10	};
 11	use chrono::{DateTime, NaiveDate, Utc};
 12	use parquet::arrow::arrow_reader::ParquetRecordBatchReaderBuilder;
 13	use serde_json::{Value, json};
 14	use sqlx::{ConnectOptions, PgPool, postgres::PgConnectOptions};
 15	use std::{
 16	    collections::{BTreeMap, BTreeSet},
 17	    fs::{self, File},
 18	    path::{Path, PathBuf},
 19	    process::Output,
 20	    time::Duration,
 21	};
 22	use tokio::{net::TcpListener, process::Command, task::JoinHandle};
 23	use uuid::Uuid;
 24	
 25	#[derive(Clone, Copy, PartialEq, Eq)]
 26	enum Fixture {
 27	    Original,
 28	    Corrected,
 29	    SourceFailure,
 30	}
 31	
 32	struct FixtureServer {
 33	    url: String,
 34	    task: JoinHandle<()>,
 35	}
 36	impl Drop for FixtureServer {
 37	    fn drop(&mut self) {
 38	        self.task.abort();
 39	    }
 40	}
 41	impl FixtureServer {
 42	    async fn start(mode: Fixture) -> Self {
 43	        let app = Router::new()
 44	            .route("/api/Members/Search", get(search))
 45	            .route("/api/Members/History", get(histories))
 46	            .with_state(mode);
 47	        let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
 48	        let url = format!("http://{}", listener.local_addr().unwrap());
 49	        let task = tokio::spawn(async move { axum::serve(listener, app).await.unwrap() });
 50	        Self { url, task }
 51	    }
 52	    async fn stop(&mut self) {
 53	        self.task.abort();
 54	        let _ = (&mut self.task).await;
 55	    }
 56	}
 57	fn profile(id: i32, mode: Fixture, current_search: bool) -> Value {
 58	    let name = if current_search {
 59	        format!("Current search profile {id}")
 60	    } else if id == 1 && mode == Fixture::Corrected {
 61	        "Corrected Member".into()
 62	    } else {
 63	        format!("Historical Member {id}")
 64	    };
 65	    json!({"value": {"id": id, "nameDisplayAs": name,
 66	        "latestParty": if id == 4 { Value::Null } else { json!({"id": 15, "name": if id == 2 && mode == Fixture::Corrected { "Corrected Party" } else { "Party" }}) },
 67	        "latestHouseMembership": {"house": if matches!(id, 2 | 4) { 2 } else { 1 }, "membershipFrom": if id == 4 { Value::Null } else { json!(" Source location ") }}
 68	    }})
 69	}
 70	async fn search(State(mode): State<Fixture>, RawQuery(query): RawQuery) -> Response {
 71	    let url = reqwest::Url::parse(&format!("http://fixture/?{}", query.unwrap())).unwrap();
 72	    let params: BTreeMap<_, _> = url.query_pairs().into_owned().collect();
 73	    assert_eq!(params["take"], "20");
 74	    let offset: usize = params["skip"].parse().unwrap();
 75	    let current = params.contains_key("IsCurrentMember");
 76	    let ids = if current {
 77	        assert_eq!(params["IsCurrentMember"], "true");
 78	        assert_eq!(params["House"], "1");
 79	        vec![1, 1, 3] // Identical repeated profiles within this stream.
 80	    } else {
 81	        assert!(!params.contains_key("House"));
 82	        assert_eq!(params["MembershipInDateRange.WasMemberOfHouse"], "1");
 83	        assert_eq!(
 84	            params["MembershipInDateRange.WasMemberOnOrAfter"],
 85	            "2024-07-04"
 86	        );
 87	        NaiveDate::parse_from_str(
 88	            &params["MembershipInDateRange.WasMemberOnOrBefore"],
 89	            "%Y-%m-%d",
 90	        )
 91	        .unwrap();
 92	        if mode == Fixture::SourceFailure && offset > 0 {
 93	            return (
 94	                StatusCode::SERVICE_UNAVAILABLE,
 95	                [("Retry-After", "0")],
 96	                "fixture unavailable",
 97	            )
 98	                .into_response();
 99	        }
100	        if mode == Fixture::Corrected {
101	            vec![1, 2, 1, 3, 4]
102	        } else {
103	            vec![1, 2, 1, 3, 4, 5]
104	        }
105	    };
106	    let items: Vec<_> = ids
107	        .iter()
108	        .skip(offset)
109	        .take(2)
110	        .map(|id| profile(*id, mode, current))
111	        .collect();
112	    // Later metadata shrinks the advertised total; clients must re-read it.
113	    Json(json!({"items": items, "totalResults": if offset == 0 { 9 } else { ids.len() }, "skip": offset, "take": 20})).into_response()
114	}
115	fn membership(house: i16, start: &str, end: Option<&str>) -> Value {
116	    json!({"house": house, "membershipStartDate": start, "membershipEndDate": end})
117	}
118	async fn histories(State(mode): State<Fixture>, RawQuery(query): RawQuery) -> Json<Value> {
119	    let url = reqwest::Url::parse(&format!("http://fixture/?{}", query.unwrap())).unwrap();
120	    let values: Vec<_> = url
121	        .query_pairs()
122	        .map(|(key, id)| {
123	            assert_eq!(key, "ids");
124	            let id: i32 = id.parse().unwrap();
125	            let periods = match id {
126	                1 => vec![
127	                    membership(1, "2020-01-01T23:30:00-02:00", None),
128	                    membership(1, "2020-01-01T23:30:00-02:00", None),
129	                ],
130	                2 => vec![
131	                    membership(
132	                        1,
133	                        "2020-01-01",
134	                        Some(if mode == Fixture::Corrected {
135	                            "2025-02-02"
136	                        } else {
137	                            "2025-01-31T23:30:00-02:00"
138	                        }),
139	                    ),
140	                    membership(2, "2025-02-03", None),
141	                ],
142	                3 => vec![
143	                    membership(1, "2020-01-01", Some("2024-12-01")),
144	                    membership(
145	                        1,
146	                        if mode == Fixture::Corrected {
147	                            "2025-02-05"
148	                        } else {
149	                            "2025-02-01"
150	                        },
151	                        None,
152	                    ),
153	                ],
154	                4 => vec![
155	                    membership(1, "2020-01-01", Some("2024-07-04")),
156	                    membership(2, "2024-07-05", None),
157	                ],
158	                5 => vec![membership(1, "2020-01-01", Some("2024-08-01"))],
159	                _ => panic!("unexpected member ID {id}"),
160	            };
161	            json!({"value": {"id": id, "houseMembershipHistory": periods}})
162	        })
163	        .collect();
164	    // The API may return histories in a different order from requested IDs.
165	    Json(json!(values.into_iter().rev().collect::<Vec<_>>()))
166	}
167	async fn command(config: &Path, operation: &str, capture_id: Option<&str>) -> Output {
168	    let mut command = Command::new(env!("CARGO_BIN_EXE_exposed"));
169	    command
170	        .args(["data", operation, "members"])
171	        .arg(config)
172	        .env_remove("DATABASE_URL");
173	    if let Some(id) = capture_id {
174	        command.arg(id);
175	    }
