181	fn success(output: &Output) -> Value {
182	    assert!(
183	        output.status.success(),
184	        "{}",
185	        String::from_utf8_lossy(&output.stderr)
186	    );
187	    let summary: Value = serde_json::from_slice(&output.stdout).unwrap();
