  1	//! One executable workflow against real HTTP, Parquet and PostgreSQL boundaries.
  2	
  3	use arrow_array::{Array, Date32Array, Int16Array, Int32Array, RecordBatch, StringArray};
  4	use axum::{
  5	    Json, Router,
  6	    extract::{RawQuery, State},
