 22	use tokio::{net::TcpListener, process::Command, task::JoinHandle};
 23	use uuid::Uuid;
 24	
 25	#[derive(Clone, Copy, PartialEq, Eq)]
 26	enum Fixture {
 27	    Original,
 28	    Corrected,
 29	    SourceFailure,
 30	}
 31	
 32	struct FixtureServer {
 33	    url: String,
 34	    task: JoinHandle<()>,
 35	}
 36	impl Drop for FixtureServer {
 37	    fn drop(&mut self) {
 38	        self.task.abort();
 39	    }
 40	}
 41	impl FixtureServer {
 42	    async fn start(mode: Fixture) -> Self {
 43	        let app = Router::new()
 44	            .route("/api/Members/Search", get(search))
 45	            .route("/api/Members/History", get(histories))
 46	            .with_state(mode);
 47	        let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
 48	        let url = format!("http://{}", listener.local_addr().unwrap());
 49	        let task = tokio::spawn(async move { axum::serve(listener, app).await.unwrap() });
 50	        Self { url, task }
 51	    }
 52	    async fn stop(&mut self) {
 53	        self.task.abort();
 54	        let _ = (&mut self.task).await;
 55	    }
 56	}
 57	fn profile(id: i32, mode: Fixture, current_search: bool) -> Value {
 58	    let name = if current_search {
 59	        format!("Current search profile {id}")
 60	    } else if id == 1 && mode == Fixture::Corrected {
 61	        "Corrected Member".into()
 62	    } else {
 63	        format!("Historical Member {id}")
 64	    };
 65	    json!({"value": {"id": id, "nameDisplayAs": name,
 66	        "latestParty": if id == 4 { Value::Null } else { json!({"id": 15, "name": if id == 2 && mode == Fixture::Corrected { "Corrected Party" } else { "Party" }}) },
 67	        "latestHouseMembership": {"house": if matches!(id, 2 | 4) { 2 } else { 1 }, "membershipFrom": if id == 4 { Value::Null } else { json!(" Source location ") }}
 68	    }})
 69	}
 70	async fn search(State(mode): State<Fixture>, RawQuery(query): RawQuery) -> Response {
 71	    let url = reqwest::Url::parse(&format!("http://fixture/?{}", query.unwrap())).unwrap();
 72	    let params: BTreeMap<_, _> = url.query_pairs().into_owned().collect();
 73	    assert_eq!(params["take"], "20");
 74	    let offset: usize = params["skip"].parse().unwrap();
 75	    let current = params.contains_key("IsCurrentMember");
 76	    let ids = if current {
 77	        assert_eq!(params["IsCurrentMember"], "true");
 78	        assert_eq!(params["House"], "1");
 79	        vec![1, 1, 3] // Identical repeated profiles within this stream.
 80	    } else {
 81	        assert!(!params.contains_key("House"));
 82	        assert_eq!(params["MembershipInDateRange.WasMemberOfHouse"], "1");
 83	        assert_eq!(
 84	            params["MembershipInDateRange.WasMemberOnOrAfter"],
 85	            "2024-07-04"
 86	        );
 87	        NaiveDate::parse_from_str(
 88	            &params["MembershipInDateRange.WasMemberOnOrBefore"],
 89	            "%Y-%m-%d",
 90	        )
 91	        .unwrap();
 92	        if mode == Fixture::SourceFailure && offset > 0 {
 93	            return (
 94	                StatusCode::SERVICE_UNAVAILABLE,
 95	                [("Retry-After", "0")],
 96	                "fixture unavailable",
 97	            )
 98	                .into_response();
 99	        }
100	        if mode == Fixture::Corrected {
101	            vec![1, 2, 1, 3, 4]
102	        } else {
