        raise ImportValidationError(
            "Current search contains members missing from historical search"
        )
    if not summary["members"]:
        raise ImportValidationError("No Commons service was found for the configured term")
    return summary


def refresh_members(
    term_start: date,
    as_of: date,
    source: MemberSource,
    store: RefreshStore,
