 65	    },
 66	}
 67	
 68	/// Run the CLI using process arguments and return its exit status.
 69	///
 70	/// Owns command dispatch, service construction, output and interruption handling.
 71	pub async fn run() -> ExitCode {
 72	    let args = Cli::parse();
 73	    // Dropping the operation on Ctrl-C drops an in-flight transaction. Capture
 74	    // publication is synchronous once source acquisition has finished.
 75	    tokio::select! {
 76	        result = dispatch(args) => match result {
 77	            Ok(()) => ExitCode::SUCCESS,
 78	            Err(error) => {
 79	                let code = if error.is::<InvalidConfiguration>() { 2 } else { 1 };
 80	                eprintln!("{error:#}");
 81	                ExitCode::from(code)
 82	            }
 83	        },
 84	        _ = tokio::signal::ctrl_c() => { eprintln!("Interrupted"); ExitCode::from(130) }
 85	    }
 86	}
 87	async fn dispatch(args: Cli) -> anyhow::Result<()> {
 88	    let outcome: EntityIngestionOutcome = match args.command {
 89	        Commands::Server { config } => {
 90	            return serve_exposed(&Config::try_from(&config)?).await;
 91	        }
 92	        Commands::Data(DataArgs {
 93	            command:
 94	                DataCommands::Fetch {
 95	                    target: FetchTarget::Members { config },
 96	                },
 97	        }) => {
 98	            let started_at = Utc::now();
 99	            let observation_date = started_at
100	                .with_timezone(&chrono_tz::Europe::London)
101	                .date_naive();
102	            let config: MemberFetchConfig = read_data_config(&config)
103	                .context(InvalidConfiguration("invalid member Fetch configuration"))?;
104	            ensure!(
105	                !config.data_root.as_os_str().is_empty(),
106	                InvalidConfiguration("data_root must not be empty")
107	            );
108	            let source = MembersApi::new(&config.members_api_url)
109	                .context(InvalidConfiguration("invalid Members API configuration"))?;
110	            let storage = ExposedDataPipeline::new(config.data_root);
111	            FetchService::new(storage, source, started_at, observation_date)
112	                .run_ingestion(&EntityIngestionRequest::new_members_request(
113	                    MemberIngestionStage::Fetch {
114	                        term_start: config.term_start,
115	                    },
116	                ))
117	                .await?
118	        }
119	        Commands::Data(DataArgs {
120	            command:
121	                DataCommands::Load {
122	                    target: LoadTarget::Members { config, capture_id },
123	                },
124	        }) => {
125	            let config: MemberLoadConfig = read_data_config(&config)
126	                .context(InvalidConfiguration("invalid member Load configuration"))?;
127	            ensure!(
128	                !config.data_root.as_os_str().is_empty(),
129	                InvalidConfiguration("data_root must not be empty")
130	            );
131	            let storage = ExposedDataPipeline::new(config.data_root);
132	            let database = MemberDatabase::new(&config.connection_string).context(
133	                InvalidConfiguration("invalid member database configuration"),
134	            )?;
135	            LoadService::new(storage, database)
136	                .run_ingestion(&EntityIngestionRequest::new_members_request(
137	                    MemberIngestionStage::Load { capture_id },
138	                ))
139	                .await?
140	        }
141	        Commands::Data(_) => {
142	            anyhow::bail!("declaration cleaning and resolution are not implemented")
143	        }
144	    };
145	    let mut summary = serde_json::to_value(outcome)?;
146	    summary["status"] = "succeeded".into();
147	    println!("{}", serde_json::to_string(&summary)?);
148	    Ok(())
149	}
150	
