 11	use uuid::Uuid;
 12	
 13	/// Identity of an immutable capture, ordered by `UUIDv7` creation time.
 14	#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Serialize, Deserialize)]
 15	#[serde(try_from = "Uuid", into = "Uuid")]
 16	pub struct CaptureId(Uuid);
 17	impl CaptureId {
 18	    /// Allocate an identity at the beginning of a fetch attempt.
 19	    #[must_use]
 20	    pub fn new() -> Self {
 21	        Self(Uuid::now_v7())
 22	    }
 23	}
 24	impl Default for CaptureId {
 25	    fn default() -> Self {
 26	        Self::new()
 27	    }
 28	}
 29	impl From<CaptureId> for Uuid {
 30	    fn from(id: CaptureId) -> Self {
 31	        id.0
 32	    }
 33	}
 34	impl TryFrom<Uuid> for CaptureId {
 35	    type Error = EntityIngestionError;
 36	    fn try_from(id: Uuid) -> Result<Self, Self::Error> {
 37	        if id.get_version_num() != 7 || id.get_variant() != uuid::Variant::RFC4122 {
 38	            return Err(invalid("capture ID must be a UUIDv7"));
 39	        }
 40	        Ok(Self(id))
 41	    }
 42	}
 43	impl FromStr for CaptureId {
 44	    type Err = EntityIngestionError;
 45	    fn from_str(value: &str) -> Result<Self, Self::Err> {
 46	        Uuid::parse_str(value)
 47	            .map_err(|_| invalid("capture ID must be a UUIDv7"))?
 48	            .try_into()
 49	    }
 50	}
 51	impl fmt::Display for CaptureId {
 52	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
 53	        self.0.fmt(f)
 54	    }
 55	}
 56	
 57	/// Valid observation context fixed when acquisition begins.
 58	#[derive(Clone, Debug, PartialEq, Eq)]
 59	pub struct CaptureContext {
 60	    capture_id: CaptureId,
 61	    term_start: NaiveDate,
 62	    observation_date: NaiveDate,
 63	    started_at: DateTime<Utc>,
 64	}
 65	impl CaptureContext {
 66	    /// Create the context used for both acquisition and offline interpretation.
 67	    ///
 68	    /// # Errors
 69	    /// Rejects a term starting after the observation date.
 70	    pub fn new(
 71	        capture_id: CaptureId,
 72	        term_start: NaiveDate,
 73	        observation_date: NaiveDate,
 74	        started_at: DateTime<Utc>,
 75	    ) -> Result<Self, EntityIngestionError> {
 76	        if term_start > observation_date {
 77	            return Err(invalid("term start is after observation date"));
 78	        }
 79	        Ok(Self {
 80	            capture_id,
 81	            term_start,
 82	            observation_date,
 83	            started_at,
 84	        })
 85	    }
 86	    /// Identity allocated for this capture.
 87	    #[must_use]
 88	    pub const fn capture_id(&self) -> CaptureId {
 89	        self.capture_id
 90	    }
 91	    /// Beginning of the Parliament cohort.
 92	    #[must_use]
 93	    pub const fn term_start(&self) -> NaiveDate {
 94	        self.term_start
 95	    }
 96	    /// Fixed calendar date in Europe/London.
 97	    #[must_use]
 98	    pub const fn observation_date(&self) -> NaiveDate {
 99	        self.observation_date
100	    }
101	    /// UTC instant at the start of acquisition.
102	    #[must_use]
103	    pub const fn started_at(&self) -> DateTime<Utc> {
104	        self.started_at
105	    }
106	}
107	
108	/// Complete source observations, checked together at construction.
109	#[derive(Clone, Debug, PartialEq, Eq)]
110	pub struct MemberObservations {
111	    profiles: Vec<MemberObservation>,
112	    current_commons: BTreeSet<i32>,
113	    histories: BTreeMap<i32, MemberHistory>,
114	}
115	impl MemberObservations {
116	    /// Accept complete candidate, current and history observations.
117	    ///
118	    /// # Errors
119	    /// Rejects duplicate, missing or unexpected identities in any dataset.
120	    pub fn new(
121	        profiles: Vec<MemberObservation>,
122	        current_commons: Vec<i32>,
123	        histories: Vec<MemberHistory>,
124	    ) -> Result<Self, EntityIngestionError> {
125	        let candidates: BTreeSet<_> = profiles
126	            .iter()
127	            .map(MemberObservation::parliament_member_id)
128	            .collect();
129	        if candidates.len() != profiles.len() {
130	            return Err(invalid("duplicate historical candidate identity"));
131	        }
132	        let current_count = current_commons.len();
133	        let current_ids: BTreeSet<_> = current_commons.into_iter().collect();
134	        if current_ids.len() != current_count || !current_ids.is_subset(&candidates) {
135	            return Err(invalid(
136	                "current Commons IDs are duplicated or missing from historical candidates",
137	            ));
138	        }
139	        let mut by_id = BTreeMap::new();
140	        for history in histories {
141	            let id = history.parliament_member_id();
142	            if by_id.insert(id, history).is_some() {
143	                return Err(invalid(format!("member {id}: duplicate history")));
144	            }
145	        }
146	        if by_id.keys().copied().collect::<BTreeSet<_>>() != candidates {
147	            return Err(invalid("histories must match requested member IDs exactly"));
148	        }
149	        Ok(Self {
150	            profiles,
151	            current_commons: current_ids,
152	            histories: by_id,
153	        })
154	    }
155	    /// Historical profiles in source order.
156	    #[must_use]
157	    pub fn profiles(&self) -> &[MemberObservation] {
158	        &self.profiles
159	    }
160	    /// Distinct current Commons identities.
161	    #[must_use]
162	    pub const fn current_commons(&self) -> &BTreeSet<i32> {
163	        &self.current_commons
164	    }
165	    /// Exactly one history for each candidate, ordered by identity.
166	    #[must_use]
167	    pub const fn histories(&self) -> &BTreeMap<i32, MemberHistory> {
168	        &self.histories
169	    }
170	}
171	
172	/// A complete capture with an explicit observation context.
173	#[derive(Clone, Debug, PartialEq, Eq)]
174	pub struct MemberCapture {
175	    context: CaptureContext,
176	    observations: MemberObservations,
177	}
178	impl MemberCapture {
179	    /// Combine valid context and complete observations.
180	    #[must_use]
181	    pub const fn new(context: CaptureContext, observations: MemberObservations) -> Self {
182	        Self {
183	            context,
184	            observations,
185	        }
186	    }
187	    /// Original acquisition context.
188	    #[must_use]
189	    pub const fn context(&self) -> &CaptureContext {
190	        &self.context
191	    }
192	    /// Complete raw observations.
193	    #[must_use]
194	    pub const fn observations(&self) -> &MemberObservations {
195	        &self.observations
196	    }
197	}
