199	/// A distinct Commons interval accepted for a particular Parliament.
200	#[derive(Clone, Debug, PartialEq, Eq)]
201	pub struct ServicePeriod {
202	    source_start_date: NaiveDate,
203	    source_end_date: Option<NaiveDate>,
204	    served_from: NaiveDate,
205	}
206	impl ServicePeriod {
207	    /// Original start used to reconcile interval identity.
208	    #[must_use]
209	    pub const fn source_start_date(&self) -> NaiveDate {
210	        self.source_start_date
211	    }
212	    /// Original date service ceased, also used as served-until.
213	    #[must_use]
214	    pub const fn source_end_date(&self) -> Option<NaiveDate> {
215	        self.source_end_date
216	    }
217	    /// Later of source start and Parliament start.
218	    #[must_use]
219	    pub const fn served_from(&self) -> NaiveDate {
220	        self.served_from
221	    }
222	}
223	
224	/// One member's nonempty, consistent Commons service for a Parliament.
225	#[derive(Clone, Debug)]
226	pub struct CommonsService {
227	    member: ParliamentMember,
228	    periods: Vec<ServicePeriod>,
229	}
230	impl CommonsService {
231	    /// Member whose current status agrees with these periods.
232	    #[must_use]
233	    pub const fn member(&self) -> &ParliamentMember {
234	        &self.member
235	    }
236	    /// Distinct and non-overlapping periods of service.
237	    #[must_use]
238	    pub fn periods(&self) -> &[ServicePeriod] {
239	        &self.periods
240	    }
241	}
242	
243	/// Entire accepted cohort, constructed before storage receives it.
244	#[derive(Clone, Debug)]
245	pub struct MemberRefresh {
246	    term_start: NaiveDate,
247	    members: Vec<CommonsService>,
248	}
249	impl MemberRefresh {
250	    /// Construct the eligible cohort using the saved observation context.
251	    ///
252	    /// # Errors
253	    /// Rejects missing required member fields, conflicting service or an empty cohort.
254	    pub fn from_capture(capture: &MemberCapture) -> Result<Self, EntityIngestionError> {
255	        let term_start = capture.context().term_start();
256	        let as_of = capture.context().observation_date();
257	        let observations = capture.observations();
258	        let mut members = Vec::new();
259	        for profile in observations.profiles() {
260	            let id = profile.parliament_member_id();
261	            let current = observations.current_commons().contains(&id);
262	            let periods =
263	                service_periods(&observations.histories()[&id], term_start, as_of, current)?;
264	            if periods.is_empty() {
265	                continue;
266	            }
267	            let required = |field| invalid(format!("member {id}: {field} is required"));
268	            let member = ParliamentMember::new(
269	                profile.name().into(),
270	                id,
271	                profile.party_id().ok_or_else(|| required("party_id"))?,
272	                profile
273	                    .party_name()
274	                    .ok_or_else(|| required("party_name"))?
275	                    .into(),
276	                profile.latest_house(),
277	                profile
278	                    .latest_membership_from()
279	                    .ok_or_else(|| required("latest_membership_from"))?
280	                    .into(),
281	                current,
282	            )?;
283	            members.push(CommonsService { member, periods });
284	        }
285	        if members.is_empty() {
286	            return Err(invalid(
287	                "no Commons service was found for the configured term",
288	            ));
289	        }
290	        Ok(Self {
291	            term_start,
292	            members,
293	        })
294	    }
295	    /// Parliament shared by every accepted member's service.
296	    #[must_use]
297	    pub const fn term_start(&self) -> NaiveDate {
298	        self.term_start
299	    }
300	    /// Accepted members and their complete Commons service.
301	    #[must_use]
302	    pub fn members(&self) -> &[CommonsService] {
