255	        let term_start = capture.context().term_start();
256	        let as_of = capture.context().observation_date();
257	        let observations = capture.observations();
258	        let mut members = Vec::new();
259	        for profile in observations.profiles() {
260	            let id = profile.parliament_member_id();
261	            let current = observations.current_commons().contains(&id);
262	            let periods =
263	                service_periods(&observations.histories()[&id], term_start, as_of, current)?;
264	            if periods.is_empty() {
265	                continue;
266	            }
267	            let required = |field| invalid(format!("member {id}: {field} is required"));
268	            let member = ParliamentMember::new(
269	                profile.name().into(),
270	                id,
271	                profile.party_id().ok_or_else(|| required("party_id"))?,
272	                profile
273	                    .party_name()
274	                    .ok_or_else(|| required("party_name"))?
275	                    .into(),
276	                profile.latest_house(),
277	                profile
278	                    .latest_membership_from()
279	                    .ok_or_else(|| required("latest_membership_from"))?
280	                    .into(),
281	                current,
282	            )?;
283	            members.push(CommonsService { member, periods });
284	        }
285	        if members.is_empty() {
286	            return Err(invalid(
287	                "no Commons service was found for the configured term",
288	            ));
289	        }
290	        Ok(Self {
291	            term_start,
292	            members,
293	        })
294	    }
295	    /// Parliament shared by every accepted member's service.
296	    #[must_use]
297	    pub const fn term_start(&self) -> NaiveDate {
298	        self.term_start
299	    }
300	    /// Accepted members and their complete Commons service.
301	    #[must_use]
302	    pub fn members(&self) -> &[CommonsService] {
303	        &self.members
304	    }
305	}
306	
307	fn service_periods(
308	    history: &MemberHistory,
309	    term_start: NaiveDate,
310	    as_of: NaiveDate,
311	    current: bool,
312	) -> Result<Vec<ServicePeriod>, EntityIngestionError> {
313	    let id = history.parliament_member_id();
314	    let memberships: BTreeSet<_> = history
315	        .house_memberships()
316	        .iter()
317	        .filter(|m| {
318	            m.house() == 1
319	                && m.start_date() <= as_of
320	                && m.end_date().is_none_or(|end| end > term_start)
321	        })
322	        .collect();
323	    let periods: Vec<_> = memberships
324	        .into_iter()
325	        .map(|m| ServicePeriod {
326	            source_start_date: m.start_date(),
327	            source_end_date: m.end_date(),
328	            served_from: m.start_date().max(term_start),
329	        })
330	        .collect();
331	    for pair in periods.windows(2) {
332	        if pair[0].source_start_date() == pair[1].source_start_date() {
333	            return Err(invalid(format!("member {id}: conflicting service starts")));
334	        }
335	        if pair[0]
336	            .source_end_date()
337	            .is_none_or(|end| pair[1].served_from() < end)
338	        {
339	            return Err(invalid(format!("member {id}: overlapping service periods")));
340	        }
341	    }
342	    let active = periods
343	        .iter()
344	        .any(|p| p.source_end_date().is_none_or(|end| end > as_of));
345	    if active != current {
346	        return Err(invalid(format!(
347	            "member {id}: history disagrees with current Commons search"
348	        )));
349	    }
350	    Ok(periods)
351	}
352	
353	pub(crate) fn invalid(message: impl Into<String>) -> EntityIngestionError {
354	    EntityIngestionError::DataError(message.into())
355	}

