  1	//! General purpose postgres client
  2	
  3	use sqlx::{
  4	    PgPool,
  5	    postgres::{PgConnectOptions, PgPoolOptions},
  6	};
  7	use std::{str::FromStr, time::Duration};
  8	
  9	/// Postgres client that wraps [`sqlx::Pool`]
 10	#[derive(Clone)]
 11	pub struct ExposedDatabase {
 12	    pool: PgPool,
 13	}
 14	
 15	impl ExposedDatabase {
 16	    /// Configure the shared database adapter without opening a connection.
 17	    ///
 18	    /// # Errors
 19	    /// Rejects an empty or invalid PostgreSQL connection string.
 20	    pub fn new_lazy(conn_str: &str) -> Result<Self, sqlx::Error> {
 21	        if conn_str.trim().is_empty() {
 22	            return Err(sqlx::Error::Configuration(
 23	                "connection_string must not be empty".into(),
 24	            ));
 25	        }
 26	        let options = PgConnectOptions::from_str(conn_str)?.application_name("exposed");
 27	        let pool = PgPoolOptions::new()
 28	            .acquire_timeout(Duration::from_secs(10))
 29	            .connect_lazy_with(options);
 30	        Ok(Self { pool })
 31	    }
 32	
 33	    /// Creates a new instance of [`ExposedDatabase`]
 34	    ///
 35	    /// # Panics
 36	    /// Invalid connection string
 37	    #[must_use]
 38	    pub async fn new(conn_str: &str) -> Self {
 39	        let pool = PgPool::connect(conn_str).await.unwrap();
 40	
 41	        Self { pool }
 42	    }
 43	
 44	    /// Get a reference to the underlying pool
 45	    #[must_use]
 46	    pub const fn pool(&self) -> &PgPool {
 47	        &self.pool
 48	    }
 49	}
