271	    fn deserialize<D: serde::Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
272	        let value = String::deserialize(deserializer)?;
273	        let date = NaiveDate::parse_from_str(&value, "%Y-%m-%d")
274	            .or_else(|_| DateTime::parse_from_rfc3339(&value).map(|d| d.date_naive()))
275	            .or_else(|_| {
276	                NaiveDateTime::parse_from_str(&value, "%Y-%m-%dT%H:%M:%S%.f").map(|d| d.date())
277	            })
278	            .or_else(|_| {
279	                NaiveDateTime::parse_from_str(&value, "%Y-%m-%d %H:%M:%S%.f").map(|d| d.date())
280	            })
281	            .map_err(serde::de::Error::custom)?;
282	        Ok(Self(date))
283	    }
