  1	//! Sequential Members API requests, typed decoding and bounded retries.
  2	use crate::domain::repositories::parliament_api::{
  3	    HouseMembership, MemberHistory, MemberObservation, ParliamentApi, ParliamentApiError,
  4	};
  5	use chrono::{DateTime, NaiveDate, NaiveDateTime};
  6	use reqwest::{Client, StatusCode, Url};
  7	use serde::{Deserialize, de::DeserializeOwned};
  8	use std::{
  9	    fmt::Display,
 10	    time::{Duration, SystemTime},
 11	};
 12	
 13	/// Production HTTP source for the Commons cohort.
 14	#[derive(Clone)]
 15	pub struct MembersApi {
 16	    client: Client,
 17	    base_url: Url,
 18	}
 19	impl MembersApi {
 20	    /// Build an HTTP client without issuing requests.
 21	    ///
 22	    /// # Errors
 23	    /// Rejects invalid URLs or HTTP client configuration.
 24	    pub fn new(base_url: &str) -> Result<Self, ParliamentApiError> {
 25	        let base_url = Url::parse(base_url).map_err(|_| failure("invalid Members API URL"))?;
 26	        if !matches!(base_url.scheme(), "http" | "https")
 27	            || base_url.host_str().is_none()
 28	            || !base_url.username().is_empty()
 29	            || base_url.password().is_some()
 30	        {
 31	            return Err(failure(
 32	                "Members API URL must be an HTTP(S) URL without credentials",
 33	            ));
 34	        }
 35	        let client = Client::builder()
 36	            .connect_timeout(Duration::from_secs(10))
 37	            .timeout(Duration::from_secs(30))
 38	            .build()
 39	            .map_err(failure)?;
 40	        Ok(Self { client, base_url })
 41	    }
 42	
 43	    async fn get<T: DeserializeOwned>(
 44	        &self,
 45	        path: &str,
 46	        params: &[(&str, String)],
 47	    ) -> Result<T, ParliamentApiError> {
 48	        let mut url = self.base_url.join(path).map_err(failure)?;
 49	        url.query_pairs_mut()
 50	            .extend_pairs(params.iter().map(|(key, value)| (*key, value.as_str())));
 51	        // Request context contains source filters/IDs, never connection credentials.
 52	        let context = format!("{path}?{}", url.query().unwrap_or_default());
 53	        for attempt in 0..4 {
 54	            tokio::time::sleep(Duration::from_millis(200)).await;
 55	            let mut delay = Duration::from_secs(1 << attempt);
 56	            let problem = match self.client.get(url.clone()).send().await {
 57	                Ok(response) => {
 58	                    let status = response.status();
 59	                    if status == StatusCode::OK {
 60	                        match response.bytes().await {
 61	                            Ok(bytes) => {
 62	                                let mut deserializer = serde_json::Deserializer::from_slice(&bytes);
 63	                                let result = serde_path_to_error::deserialize(&mut deserializer)
 64	                                    .map_err(|error| failure(format!("{context}: {error}")))?;
 65	                                deserializer
 66	                                    .end()
 67	                                    .map_err(|error| failure(format!("{context}: {error}")))?;
 68	                                return Ok(result);
 69	                            }
 70	                            Err(error) => format!("response transport failure: {error}"),
 71	                        }
 72	                    } else {
 73	                        if status != StatusCode::TOO_MANY_REQUESTS && !status.is_server_error() {
 74	                            return Err(failure(format!("{context}: HTTP {status}")));
 75	                        }
 76	                        if let Some(header) = response
 77	                            .headers()
 78	                            .get(reqwest::header::RETRY_AFTER)
 79	                            .and_then(|h| h.to_str().ok())
 80	                        {
 81	                            delay = retry_delay(header).unwrap_or(delay);
 82	                        }
 83	                        format!("HTTP {status}")
 84	                    }
 85	                }
 86	                Err(error) => format!("transport failure: {error}"),
 87	            };
 88	            if attempt == 3 {
 89	                return Err(failure(format!("{context}: {problem} after four attempts")));
 90	            }
 91	            eprintln!("{context}: {problem}; retry {}/4", attempt + 2);
 92	            tokio::time::sleep(delay.min(Duration::from_secs(30))).await;
 93	        }
 94	        unreachable!("four attempts always return success or failure")
 95	    }
 96	
 97	    async fn search(
 98	        &self,
 99	        filters: Vec<(&str, String)>,
100	    ) -> Result<Vec<MemberObservation>, ParliamentApiError> {
101	        let mut profiles = Vec::new();
102	        let mut offset = 0;
103	        loop {
104	            let mut params = filters.clone();
105	            params.extend([("skip", offset.to_string()), ("take", "20".to_owned())]);
106	            let page: SearchPage = self.get("/api/Members/Search", &params).await?;
107	            let context = format!("/api/Members/Search {params:?}");
108	            if page.skip != offset {
109	                return Err(failure(format!(
110	                    "{context}: response skip {} does not match request {offset}",
111	                    page.skip
112	                )));
113	            }
114	            if page.items.is_empty() && offset < page.total_results {
115	                return Err(failure(format!(
116	                    "{context}: premature empty page before total {}",
117	                    page.total_results
118	                )));
119	            }
120	            offset = offset
121	                .checked_add(page.items.len())
122	                .ok_or_else(|| failure("search pagination overflow"))?;
123	            for item in page.items {
124	                profiles.push(
125	                    MemberObservation::new(
126	                        item.value.id,
127	                        item.value.name_display_as,
128	                        item.value.latest_party.as_ref().and_then(|p| p.id),
129	                        item.value.latest_party.and_then(|p| p.name),
130	                        item.value.latest_house_membership.house,
131	                        item.value.latest_house_membership.membership_from,
132	                    )
133	                    .map_err(|error| failure(format!("{context}: {error}")))?,
134	                );
135	            }
136	            if offset >= page.total_results {
137	                return Ok(profiles);
138	            }
139	        }
140	    }
141	}
142	
143	impl ParliamentApi for MembersApi {
144	    async fn current_commons(&self) -> Result<Vec<MemberObservation>, ParliamentApiError> {
145	        self.search(vec![
146	            ("House", "1".into()),
147	            ("IsCurrentMember", "true".into()),
148	        ])
149	        .await
150	    }
151	    async fn commons_candidates(
152	        &self,
153	        term_start: NaiveDate,
154	        observation_date: NaiveDate,
155	    ) -> Result<Vec<MemberObservation>, ParliamentApiError> {
156	        self.search(vec![
157	            (
158	                "MembershipInDateRange.WasMemberOnOrAfter",
159	                term_start.to_string(),
160	            ),
161	            (
162	                "MembershipInDateRange.WasMemberOnOrBefore",
163	                observation_date.to_string(),
164	            ),
165	            ("MembershipInDateRange.WasMemberOfHouse", "1".into()),
166	        ])
167	        .await
168	    }
169	    async fn member_histories(
170	        &self,
171	        member_ids: &[i32],
172	    ) -> Result<Vec<MemberHistory>, ParliamentApiError> {
173	        if member_ids.is_empty() || member_ids.len() > 100 {
174	            return Err(failure("history requests require 1–100 member IDs"));
175	        }
176	        let params: Vec<_> = member_ids
177	            .iter()
178	            .map(|id| ("ids", id.to_string()))
179	            .collect();
180	        let items: Vec<Item<History>> = self.get("/api/Members/History", &params).await?;
181	        items
182	            .into_iter()
183	            .map(|item| {
184	                let id = item.value.id;
185	                let periods = item
186	                    .value
187	                    .house_membership_history
188	                    .into_iter()
189	                    .map(|period| {
190	                        HouseMembership::new(
191	                            period.house,
192	                            period.start_date.0,
193	                            period.end_date.map(|date| date.0),
194	                        )
195	                        .map_err(|error| {
196	                            failure(format!("/api/Members/History, member {id}: {error}"))
197	                        })
198	                    })
199	                    .collect::<Result<Vec<_>, _>>()?;
200	                MemberHistory::new(id, periods)
201	                    .map_err(|error| failure(format!("/api/Members/History: {error}")))
202	            })
203	            .collect()
204	    }
205	}
206	
207	fn failure(message: impl Display) -> ParliamentApiError {
208	    ParliamentApiError(message.to_string())
209	}
210	fn retry_delay(header: &str) -> Option<Duration> {
211	    if let Ok(seconds) = header.parse::<f64>() {
212	        return seconds
213	            .is_finite()
214	            .then(|| Duration::from_secs_f64(seconds.clamp(0.0, 30.0)));
215	    }
216	    httpdate::parse_http_date(header).ok().map(|date| {
217	        date.duration_since(SystemTime::now())
218	            .unwrap_or_default()
219	            .min(Duration::from_secs(30))
220	    })
221	}
222	
223	#[derive(Deserialize)]
224	struct Item<T> {
225	    value: T,
226	}
227	#[derive(Deserialize)]
