 32	            || base_url.password().is_some()
 33	        {
 34	            return Err(failure(
 35	                "Members API URL must be an HTTP(S) URL without credentials",
 36	            ));
 37	        }
 38	        let client = Client::builder()
 39	            .connect_timeout(Duration::from_secs(10))
 40	            .timeout(Duration::from_secs(30))
 41	            .build()
 42	            .map_err(failure)?;
 43	        Ok(Self { client, base_url })
 44	    }
