 46	    async fn get<T: DeserializeOwned>(
 47	        &self,
 48	        path: &str,
 49	        params: &[(&str, String)],
 50	    ) -> Result<T, ParliamentApiError> {
 51	        let mut url = self.base_url.join(path).map_err(failure)?;
 52	        url.query_pairs_mut()
 53	            .extend_pairs(params.iter().map(|(key, value)| (*key, value.as_str())));
 54	        // Request context contains source filters/IDs, never connection credentials.
 55	        let context = format!("{path}?{}", url.query().unwrap_or_default());
 56	        for attempt in 0..4 {
 57	            tokio::time::sleep(Duration::from_millis(200)).await;
 58	            let mut delay = Duration::from_secs(1 << attempt);
 59	            let problem = match self.client.get(url.clone()).send().await {
 60	                Ok(response) => {
