//! Typed requests and outcomes for independent ingestion operations.

use super::member_ingestion::CaptureId;
use crate::domain::repositories::{
    entity_ingestion_pipline::EntitySearchPipelineError, parliament_api::ParliamentApiError,
    parliament_member_repository::ParliamentMemberRepoError,
};
use chrono::NaiveDate;
use serde::Serialize;
use std::str::FromStr;
use strum::EnumString;
use thiserror::Error;

/// A single explicitly selected ingestion operation.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct EntityIngestionRequest {
    target: EntityIngestionTarget,
}

impl EntityIngestionRequest {
    /// Select member acquisition or offline loading.
    #[must_use]
    pub const fn new_members_request(stage: MemberIngestionStage) -> Self {
        Self {
            target: EntityIngestionTarget::Members(stage),
        }
    }
    /// Select an existing declaration stage (implementation is deferred).
    ///
    /// # Errors
    /// Returns an error for an unknown stage name.
    pub fn new_declaration_request(stage: &str) -> Result<Self, EntityIngestionError> {
        let stage = DeclarationIngestionStage::from_str(stage)
            .map_err(|_| EntityIngestionError::InvalidStage(stage.to_string()))?;
        Ok(Self {
            target: EntityIngestionTarget::Declaration(stage),
        })
    }
    /// Operation selected by this request.
    #[must_use]
    pub const fn target(&self) -> &EntityIngestionTarget {
        &self.target
    }
}

/// Ingestion targets.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum EntityIngestionTarget {
    /// Member capture or database publication.
    Members(MemberIngestionStage),
    /// Declaration stages remain deferred.
    Declaration(DeclarationIngestionStage),
}

/// Independent member operations with distinct inputs.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum MemberIngestionStage {
    /// Acquire source data for the configured Parliament.
    Fetch {
        /// Beginning of the Parliament cohort.
        term_start: NaiveDate,
    },
    /// Apply a completed capture entirely offline from Parliament.
    Load {
        /// Explicit `UUIDv7` of the saved input.
        capture_id: CaptureId,
    },
}

/// From what stage to run the declaration pipeline.
#[derive(Clone, Debug, PartialEq, Eq, EnumString)]
#[allow(missing_docs)]
#[strum(ascii_case_insensitive)]
pub enum DeclarationIngestionStage {
    Import,
    Clean,
    Resolve,
}

/// Success is returned only after finalization or transaction commit.
#[derive(Clone, Debug, Serialize)]
#[serde(tag = "operation", rename_all = "snake_case")]
pub enum EntityIngestionOutcome {
    /// Completed immutable source capture.
    Fetch {
        /// Completed capture identity.
        capture_id: CaptureId,
    },
    /// Committed database refresh.
    Load {
        /// Explicit capture used for the refresh.
        capture_id: CaptureId,
        /// Captured term start.
        term_start: NaiveDate,
        /// Captured observation date.
        observation_date: NaiveDate,
    },
}

/// Failures while acquiring, validating or publishing ingestion data.
#[derive(Error, Debug)]
pub enum EntityIngestionError {
    /// Source request or decoding failure.
    #[error("Parliament source: {0}")]
    ApiError(#[from] ParliamentApiError),
    /// Invalid source observations or service rules.
    #[error("invalid member data: {0}")]
    DataError(String),
    /// Capture storage failure.
    #[error("capture storage: {0}")]
    IoError(#[from] EntitySearchPipelineError),
    /// Atomic database refresh failed.
    #[error("member load: {0}")]
    DatabaseError(#[from] ParliamentMemberRepoError),
    /// Invalid or unavailable stage.
    #[error("unsupported ingestion stage: {0}")]
    InvalidStage(String),
}
//! Source observations needed to reproduce a configured Commons cohort.
use crate::domain::models::parliament_member::ParliamentMember;
use chrono::NaiveDate;
use thiserror::Error;

/// Parliament source capability, used only by Fetch.
pub trait ParliamentApi: Clone + Send + Sync + 'static {
    /// Current Commons observations, retaining repeats for comparison within this stream.
    fn current_commons(
        &self,
    ) -> impl Future<Output = Result<Vec<ParliamentMember>, ParliamentApiError>> + Send;
    /// Historical candidates without filtering on their latest House or current status.
    fn commons_candidates(
        &self,
        term_start: NaiveDate,
        observation_date: NaiveDate,
    ) -> impl Future<Output = Result<Vec<ParliamentMember>, ParliamentApiError>> + Send;
    /// Histories for the requested IDs, retaining returned identities and duplicates.
    fn member_histories(
        &self,
        member_ids: &[i32],
    ) -> impl Future<Output = Result<Vec<MemberHistory>, ParliamentApiError>> + Send;
}

/// Source failure with request and field context.
#[derive(Error, Debug)]
#[error("{0}")]
pub struct ParliamentApiError(pub String);

/// One source House membership, before term clipping or deduplication.
#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub struct HouseMembership {
    house: i16,
    start_date: NaiveDate,
    end_date: Option<NaiveDate>,
}
impl HouseMembership {
    /// Accept a source period without deriving Commons service from it.
    ///
    /// # Errors
    /// Rejects an unknown House or an end date before the start.
    pub fn new(
        house: i16,
        start_date: NaiveDate,
        end_date: Option<NaiveDate>,
    ) -> Result<Self, ParliamentApiError> {
        if !matches!(house, 1 | 2) || end_date.is_some_and(|end| end < start_date) {
            return Err(ParliamentApiError(
                "invalid House or membership date ordering".into(),
            ));
        }
        Ok(Self {
            house,
            start_date,
            end_date,
        })
    }
    /// Commons (1) or Lords (2).
    #[must_use]
    pub const fn house(&self) -> i16 {
        self.house
    }
    /// Source calendar start date.
    #[must_use]
    pub const fn start_date(&self) -> NaiveDate {
        self.start_date
    }
    /// Date service ceased, if supplied.
    #[must_use]
    pub const fn end_date(&self) -> Option<NaiveDate> {
        self.end_date
    }
}

/// A returned history, retaining its source identity and every period.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct MemberHistory {
    parliament_member_id: i32,
    house_memberships: Vec<HouseMembership>,
}
impl MemberHistory {
    /// Accept one identified, nonempty source history.
    ///
    /// # Errors
    /// Rejects an invalid member identity or an empty history.
    pub fn new(
        parliament_member_id: i32,
        house_memberships: Vec<HouseMembership>,
    ) -> Result<Self, ParliamentApiError> {
        if parliament_member_id <= 0 || house_memberships.is_empty() {
            return Err(ParliamentApiError(format!(
                "member {parliament_member_id}: invalid identity or empty history"
            )));
        }
        Ok(Self {
            parliament_member_id,
            house_memberships,
        })
    }
    /// Parliament's numeric identity.
    #[must_use]
    pub const fn parliament_member_id(&self) -> i32 {
        self.parliament_member_id
    }
    /// All source periods, including identical repeats.
    #[must_use]
    pub fn house_memberships(&self) -> &[HouseMembership] {
        &self.house_memberships
    }
}

