   121	    for batch in read_batches(&path.join("profiles.parquet"), &profiles_schema())? {
   122	        let ids: &Int32Array = column(&batch, 0)?;
   123	        let names: &StringArray = column(&batch, 1)?;
   124	        let parties: &Int32Array = column(&batch, 2)?;
   125	        let party_names: &StringArray = column(&batch, 3)?;
   126	        let houses: &Int16Array = column(&batch, 4)?;
   127	        let locations: &StringArray = column(&batch, 5)?;
   128	        for row in 0..batch.num_rows() {
