   184	fn read_batches(path: &Path, schema: &SchemaRef) -> anyhow::Result<Vec<RecordBatch>> {
   185	    let result = (|| {
   186	        let builder = ParquetRecordBatchReaderBuilder::try_new(File::open(path)?)?;
   187	        // Earlier schema-v1 captures marked profile columns nullable. Accept
   188	        // their metadata, but require every now-required value below.
   189	        let fields = builder.schema().fields();
   190	        ensure!(
   191	            fields.len() == schema.fields().len()
   192	                && fields
   193	                    .iter()
   194	                    .zip(schema.fields())
   195	                    .all(|(actual, expected)| {
   196	                        actual.name() == expected.name()
   197	                            && actual.data_type() == expected.data_type()
   198	                    }),
   199	            "Parquet types or fields do not match schema v1"
   200	        );
   201	        let batches = builder.build()?.collect::<Result<Vec<_>, _>>()?;
   202	        for batch in &batches {
   203	            for (field, column) in schema.fields().iter().zip(batch.columns()) {
   204	                ensure!(
   205	                    field.is_nullable() || column.null_count() == 0,
   206	                    "required column {} contains nulls",
   207	                    field.name()
   208	                );
   209	            }
   210	        }
   211	        Ok(batches)
   212	    })();
   213	    result.with_context(|| format!("read {}", path.display()))
   214	}
   215	fn column<T: Array + 'static>(batch: &RecordBatch, index: usize) -> anyhow::Result<&T> {
   216	    batch
   217	        .column(index)
   218	        .as_any()
   219	        .downcast_ref()
   220	        .context("unexpected Parquet column type")
   221	}

